    fixture.ok(&["rm", "kept", "--yes"]);

    let (output, rows) = fixture.pick(&["work", "restore"], picked["id"].as_str().unwrap(), "");
    assert!(output.status.success(), "{output:?}");
    let rows = rows.lines().collect::<Vec<_>>();
    assert_eq!(rows.len(), 2, "{rows:?}");
