#[test]
fn add_issue_takes_the_repository_of_the_current_checkout_or_workspace() {
    let fixture = Fixture::with_config(Some(
        "[agents.reviewer]\ncommand = ['printf', '%s', '{prompt}']\n",
    ));
    forge_origin(&fixture);
    let bin = fixture.root.path().join("issue-bin");
    // The daemon reads the issue through the scripted curl.
    install_api_curl(&fixture.root.path().join("bin"));
    script_api(
        fixture.root.path(),
        "repos/team/project/issues/12",
        &serde_json::json!({"number": 12, "title": "Clarify retries", "state": "open",
            "body": "", "labels": [], "pull_request": null}),
    );
    let path = format!("{}:{}", bin.display(), std::env::var("PATH").unwrap());
    // No terminal, as in a planning chat's tool call: no picker may run.
    let add = |cwd: &Path| {
        let output = fixture
            .command()
            .args([
                "--json", "start", "--issue", "12", "--here", "--agent", "reviewer",
            ])
            .current_dir(cwd)
            .env("PATH", &path)
            .output()
            .unwrap();
        assert!(output.status.success(), "{output:?}");
        serde_json::from_str::<Value>(
            String::from_utf8_lossy(&output.stdout)
                .lines()
                .next()
                .unwrap(),
        )
        .unwrap()
    };
    let created = add(&fixture.repo);
    assert_eq!(created["name"], "12-clarify-retries");
    let workspace = PathBuf::from(created["path"].as_str().unwrap());
    assert_eq!(add(&workspace)["id"], created["id"]);
    assert_eq!(fixture.ok(&["work"]).as_array().unwrap().len(), 1);
}

#[test]
fn a_chat_reviews_its_linked_pr_and_lists_and_cancels_that_review() {
    let fixture = Fixture::with_config(Some(
        "agent.default = 'reviewer'\n[agents.reviewer]\ncommand = ['sh']\nreview = ['-c', 'exit 1', '{prompt}', '{schema}']\n",
    ));
    let author = forge_origin(&fixture);
    git(&author, &["switch", "-c", "fix"]);
    fs::write(author.join("fix"), "change\n").unwrap();
    git(&author, &["add", "fix"]);
    git(
        &author,
        &[
            "-c",
            "user.name=Test",
            "-c",
            "user.email=test@example.invalid",
            "commit",
            "-m",
            "fix",
        ],
    );
    git(&author, &["push", "origin", "fix"]);
    let bin = fixture.root.path().join("bin");
    install_api_curl(&bin);
    let mut pull = forgejo_pull(7, "open", "fix", &"7".repeat(40));
    pull["head"]["repo"]["full_name"] = "team/project".into();
    script_api(fixture.root.path(), "repos/team/project/pulls/7", &pull);
    let path = format!("{}:{}", bin.display(), std::env::var("PATH").unwrap());
    let (mut agent, _) = start_test_chat(&fixture, "planning");
    let run = |args: &[&str]| {
        fixture
            .command()
            .arg("--json")
            .args(args)
            .current_dir(&fixture.repo)
            .env("PATH", &path)
            .output()
            .unwrap()
    };
    // Nothing linked: nothing to review.
    let output = run(&["review", "run", "planning", "--agent", "reviewer"]);
    assert!(!output.status.success(), "{output:?}");
    let output = run(&["link", "pr", "7", "assigned", "--space", "planning"]);
    assert!(output.status.success(), "{output:?}");
    // The linked PR is reviewed in the workspace that owns its head, and
    // posting applies to it.
    let output = run(&["review", "run", "planning", "--no-post"]);
    assert!(output.status.success(), "{output:?}");
    let ended = fixture.ok(&["watch", "review", "1"]);
    let url = "https://forge.example/team/project/pulls/7";
    assert_eq!(ended["target"]["url"], url, "{ended}");
    assert_eq!(ended["target"]["post"], false, "{ended}");
    let listed = fixture.ok(&["review", "list", "planning"]);
    assert_eq!(listed[0]["id"], 1, "{listed}");
    let output = run(&["review", "cancel", "--space", "planning"]);
    assert!(!output.status.success(), "{output:?}");
    agent.kill().unwrap();
    agent.wait().unwrap();
}

#[test]
fn review_opens_a_pr_head_against_its_base_and_reuses_the_owner() {
    let fixture = Fixture::with_config(Some(
        "agent.default = 'reviewer'\n[agents.reviewer]\ncommand = ['sh']\nreview = ['-c', 'exit 1', '{prompt}', '{schema}']\n",
    ));
    let author = forge_origin(&fixture);
    let commit = |message: &str| {
        fs::write(author.join(message), "change\n").unwrap();
        git(&author, &["add", message]);
        git(
            &author,
            &[
                "-c",
                "user.name=Test",
                "-c",
                "user.email=test@example.invalid",
                "commit",
                "-m",
                message,
            ],
        );
    };
    git(&author, &["switch", "-c", "stack/base"]);
    commit("base");
    git(&author, &["switch", "-c", "stack/top"]);
    commit("top");
    git(&author, &["push", "origin", "stack/base", "stack/top"]);

    // The daemon also queries the PR when linking it, through the fixture's bin.
    let bin = fixture.root.path().join("bin");
    install_api_curl(&bin);
    let mut pull = forgejo_pull(7, "open", "stack/top", &"7".repeat(40));
    pull["title"] = "Top change".into();
    pull["base"]["ref"] = "stack/base".into();
    pull["head"]["repo"]["full_name"] = "team/project".into();
    script_api(fixture.root.path(), "repos/team/project/pulls/7", &pull);
    let path = format!("{}:{}", bin.display(), std::env::var("PATH").unwrap());
    let review = |target: &[&str]| {
        fixture
            .command()
            .args(["review", "run"])
            .args(target)
            .args(["--agent", "reviewer"])
            .current_dir(&fixture.repo)
            .env("PATH", &path)
            .output()
            .unwrap()
    };
    let output = review(&["--pr", "7"]);
    assert!(output.status.success(), "{output:?}");
    // The review covers the PR's head against its base, both from origin.
    let ended = fixture.ok(&["watch", "review", "1"]);
    assert_eq!(ended["target"]["head"], "stack/top", "{ended}");
    assert_eq!(ended["target"]["base"], "stack/base", "{ended}");
    assert_eq!(
        ended["head"],
        git(&author, &["rev-parse", "stack/top"]).trim()
    );
    assert_eq!(ended["failure"], "execution-failed");
    assert!(
        fs::read_to_string(fixture.root.path().join("curl-urls"))
            .unwrap()
            .contains("https://forge.example/api/v1/repos/team/project/pulls/7\n")
    );
    let url = "https://forge.example/team/project/pulls/7";
    let linked_prs =
        || fixture.ok(&["work", "status", "stack-top"])["workspace"]["links"]["prs"].clone();
    assert_eq!(linked_prs(), serde_json::json!([url]));
    // Opening the PR again relinks it to its owner.
    fixture.ok(&["unlink", "pr", url, "assigned", "--space", "stack-top"]);
    assert_eq!(linked_prs(), serde_json::json!([]));
    let added = fixture
        .command()
        .args([
            "--json",
            "start",
            "https://forge.example/team/project/pulls/7",
        ])
        .env("PATH", &path)
        .output()
        .unwrap();
    assert!(added.status.success(), "{added:?}");
    assert_eq!(linked_prs(), serde_json::json!([url]));
    let added: Value = serde_json::from_slice(&added.stdout).unwrap();
    assert_eq!(added["branch"], "stack/top");
    assert_eq!(added["links"]["prs"], serde_json::json!([url]));
    let branch = fixture.ok(&[
        "start",
        "https://forge.example/team/project/src/branch/stack%2Ftop",
    ]);
    assert_eq!(branch["id"], added["id"]);
    let workspace = &fixture.ok(&["work", "status", "stack-top"])["workspace"];
    assert_eq!(workspace["base_ref"], "refs/remotes/origin/stack/base");
    let path_in = Path::new(workspace["path"].as_str().unwrap());
    assert_eq!(
        git(
            path_in,
            &["merge-base", "--fork-point", "origin/stack/base", "HEAD"]
        ),
        git(&author, &["rev-parse", "stack/base"])
    );

    // Reviewing in the owner links the PR as well.
    fixture.ok(&["unlink", "pr", url, "assigned", "--space", "stack-top"]);
    commit("more");
    git(&author, &["push", "origin", "stack/top"]);
    let output = review(&["https://forge.example/team/project/pulls/7", "--no-post"]);
    assert!(output.status.success(), "{output:?}");
    assert_eq!(linked_prs(), serde_json::json!([url]));
    assert_eq!(
        fixture.ok(&["watch", "review", "2"])["target"]["post"],
        false
    );
    assert!(path_in.join("more").exists());
    // A diverged workspace is left for the reviewer to reconcile.
    git(path_in, &["reset", "--hard", "HEAD~1"]);
    fs::write(path_in.join("local"), "change\n").unwrap();
    git(path_in, &["add", "local"]);
    git(
        path_in,
        &[
            "-c",
            "user.name=Test",
            "-c",
            "user.email=test@example.invalid",
            "commit",
            "-m",
            "local",
        ],
    );
    assert!(!review(&["--pr", "7"]).status.success());
    let output = review(&["https://forge.example/other/project/pulls/7"]);
    assert!(!output.status.success());
}

#[test]
fn repository_config_sets_the_automatic_port_range() {
    let fixture = Fixture::new();
    let workspace = fixture.add("ranged");
    let path = Path::new(workspace["path"].as_str().unwrap());
    let [first, second] = [(); 2].map(|()| ports::hold()).map(|held| held.port);
    fs::write(
        path.join(".shoal.toml"),
        format!("[ports]\nstart={first}\nend={first}\n"),
    )
    .unwrap();
    assert_eq!(
        fixture.ok(&["acquire", "port", "web", "--workspace", "ranged"])["port"],
        first
    );
    assert!(
        !fixture
            .run(&["acquire", "port", "api", "--workspace", "ranged"])
            .status
            .success()
    );
    // The saved config is the top layer, bound by bound.
    let saved = fixture.root.path().join("saved.toml");
    let save = |text: &str| {
        fs::write(&saved, text).unwrap();
        fixture.save_local_config(fixture.repo.to_str().unwrap(), &saved);
    };
    save(&format!("[ports]\nstart={second}\nend={second}\n"));
    assert_eq!(
        fixture.ok(&["acquire", "port", "api", "--workspace", "ranged"])["port"],
        second
    );
    // The layered range must stay nonempty: `end = 1` under the file's `start`.
    save("[ports]\nend=1\n");
    let output = fixture.run(&["acquire", "port", "db", "--workspace", "ranged"]);
    assert!(!output.status.success());
}

#[test]
fn config_show_reports_effective_values_and_their_layers() {
    let fixture = Fixture::with_config(Some(
        "agent.default = 'claude'\n[commands]\nglobal = ['global']\nshared = ['global']\n\
         [cleanup.auto]\nenabled = false\n[ports]\nstart = 2000\nend = 6000\n",
    ));

    // In a registered checkout without a workspace, the checkout file is the
    // worktree layer for the current-directory target.
    fs::write(
        fixture.repo.join(".shoal.toml"),
        "hooks.post_setup = 'checkout/attach'\n",
    )
    .unwrap();
    let checkout = fixture
        .command()
        .current_dir(&fixture.repo)
        .args(["--json", "config", "show"])
        .output()
        .unwrap();
    assert!(checkout.status.success());
    let checkout: Value = serde_json::from_slice(&checkout.stdout).unwrap();
    let checkout_entry = checkout
        .as_array()
        .unwrap()
        .iter()
        .find(|entry| entry["key"] == "hooks.post_setup")
        .unwrap();
    assert_eq!(checkout_entry["value"], "checkout/attach");
    assert_eq!(checkout_entry["layer"], "worktree_file");
    fs::remove_file(fixture.repo.join(".shoal.toml")).unwrap();

    let workspace = fixture.add("layered-config");
    let path = Path::new(workspace["path"].as_str().unwrap());
    fs::write(
        path.join(".shoal.toml"),
        "setup.command = 'scripts/setup'\n[commands]\nworktree = ['worktree']\nshared = ['worktree']\n\
         [ports]\nstart = 3000\n[ports.web]\nenv = 'WORKTREE_PORT'\n",
    )
    .unwrap();
    let saved = fixture.root.path().join("saved-config.toml");
    fs::write(
        &saved,
        "agent.default = 'codex'\n[commands]\nshared = ['saved']\n[ports]\nend = 4000\n",
    )
    .unwrap();
    fixture.save_local_config(fixture.repo.to_str().unwrap(), &saved);

    let report = fixture.ok(&["config", "show", "layered-config"]);
    let entry = |key: &str| {
        report
            .as_array()
            .unwrap()
            .iter()
            .find(|entry| entry["key"] == key)
            .unwrap()
    };
    for (key, value, layer) in [
        ("agent.default", serde_json::json!("codex"), "local_config"),
        (
            "commands.shared",
            serde_json::json!(["saved"]),
            "local_config",
        ),
        ("ports.start", serde_json::json!(3000), "worktree_file"),
        ("ports.end", serde_json::json!(4000), "local_config"),
        (
            "commands.global",
            serde_json::json!(["global"]),
            "global_config",
        ),
        (
            "cleanup.auto.idle_minutes",
            serde_json::json!(10),
            "built_in_default",
        ),
    ] {
        assert_eq!(entry(key)["value"], value, "{key}");
        assert_eq!(entry(key)["layer"], layer, "{key}");
    }

    // A named repository is shown as in its registered checkout.
    let repository = fixture.ok(&["config", "show", "--repo", fixture.repo.to_str().unwrap()]);
    let entry = |key: &str| {
        repository
            .as_array()
            .unwrap()
            .iter()
            .find(|entry| entry["key"] == key)
            .unwrap()
    };
    assert_eq!(entry("agent.default")["value"], "codex");
    assert_eq!(entry("agent.default")["layer"], "local_config");
}

#[test]
fn configured_port_range_exhaustion_and_release() {
    // Another process on a shared runner can bind the port after the test
    // releases it, so a taken port starts the check over on a fresh one.
    for _ in 0..5 {
        if port_range_exhaustion_and_release() {
            return;
        }
    }
    panic!("other processes took every released test port");
}

/// False when another process bound the configured port once the test
/// stopped holding it.
fn port_range_exhaustion_and_release() -> bool {
    let held = ports::hold();
    let number = held.port;
    let fixture = Fixture::with_config(Some(&format!("[ports]\nstart={number}\nend={number}\n")));
    fixture.add("limited");
    let acquire =
        |name: &str| fixture.run(&["--json", "acquire", "port", name, "--workspace", "limited"]);
    assert!(!acquire("web").status.success());
    drop(held);
    let Some(lease) = port_lease(acquire("web")) else {
        return false;
    };
    assert_eq!(lease["port"], number);
    assert!(!acquire("api").status.success());
    fixture.ok(&["release", "port", "web", "--workspace", "limited"]);
    let Some(lease) = port_lease(acquire("api")) else {
        return false;
    };
    assert_eq!(lease["port"], number);
    fixture.ok(&["rm", "limited"]);
    true
}

/// The granted lease, or `None` when no port in the range was free to bind.
fn port_lease(output: Output) -> Option<Value> {
    if output.status.success() {
        return Some(serde_json::from_slice(&output.stdout).unwrap());
    }
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(stderr.contains("no available TCP ports"), "{stderr}");
    None
}

#[test]
fn concurrent_adds_cannot_claim_the_same_name() {
    let fixture = Fixture::new();
    for (first_name, second_name, workspace_name) in [
        ("shared", "shared", "shared"),
        ("shared/topic", "shared-topic", "shared-topic"),
    ] {
        let first = fixture
            .command()
            .args(["start", fixture.repo.to_str().unwrap(), first_name])
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        let second = fixture.run(&["start", fixture.repo.to_str().unwrap(), second_name]);
        let first = first.wait_with_output().unwrap();
        assert_ne!(first.status.success(), second.status.success());
        assert_eq!(fixture.ok(&["work"]).as_array().unwrap().len(), 1);
        fixture.ok(&["rm", workspace_name]);
    }
}

#[test]
fn branch_names_are_preserved_with_portable_workspace_names() {
    let fixture = Fixture::new();
    let long = format!("long/{}", "x".repeat(100));
    let sha1 = "a".repeat(40);
    let sha256 = "b".repeat(64);
    for (branch, name) in [
        (
            "henrik/8374-set-league-season-player-profile",
            "henrik-8374-set-league-season-player-profile",
        ),
        ("release/v1.2", "release-v1-2"),
        ("feature/æøå-日本語", "feature--------"),
        ("_private", "private"),
        ("+special", "special"),
        ("@", "workspace"),
        (sha1.as_str(), sha1.as_str()),
        (sha256.as_str(), sha256.as_str()),
        ("refs/heads/topic", "refs-heads-topic"),
        ("topic/-leaf", "topic--leaf"),
        ("\u{2003}topic\u{2003}", "topic-"),
        (
            "topic/quote'\";$`(literal)&{ok}",
            "topic-quote------literal---ok-",
        ),
        (long.as_str(), &format!("long-{}", "x".repeat(59))),
    ] {
        git(&fixture.repo, &["check-ref-format", "--branch", branch]);
        let workspace = fixture.add(branch);
        let actual_branch = if branch == "@" || branch == sha1 || branch == sha256 {
            format!("{branch}-2")
        } else {
            branch.to_owned()
        };
        assert_eq!(workspace["branch"], actual_branch);
        assert_eq!(workspace["name"], name, "{branch}");
        let path = Path::new(workspace["path"].as_str().unwrap());
        assert_eq!(path.file_name().unwrap(), name);
        assert_eq!(
            git(path, &["symbolic-ref", "HEAD"]),
            format!("refs/heads/{actual_branch}\n")
        );
        assert_eq!(fixture.ok(&["rm", name])["branch_deleted"], true);
    }
}

#[test]
fn a_scoped_start_refuses_a_detached_agent_without_zmx_before_creating_the_child() {
    let fixture =
        Fixture::with_config(Some("[agents.droid]\ncommand = ['fake-droid', '{args}']\n"));
    let bin = fixture.root.path().join("bin");
    install_test_script_with_mode(bin.join("fake-droid"), "#!/bin/sh\nexit 0\n", 0o700);
    fixture.add("parent");
    // Outside Herdr the daemon starts the parent agent's child agent in a
    // detached zmx session.
    let output = fixture
        .command()
        .args([
            "run",
            "--workspace",
            "parent",
            "--",
            support::shoal_binary(),
            "start",
            fixture.repo.to_str().unwrap(),
            "child",
            "--agent",
            "droid",
        ])
        .env(
            "PATH",
            format!("{}:{}", bin.display(), fixture.system_path()),
        )
        .output()
        .unwrap();
    assert!(!output.status.success());
    assert_eq!(fixture.ok(&["work"]).as_array().unwrap().len(), 1);
}

