#[test]
fn configured_ports_are_lazy_and_conflicts_require_acceptance() {
    let fixture = Fixture::new();
    let occupied = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let preferred = occupied.local_addr().unwrap().port();
    fs::write(
        fixture.repo.join(".shoal.toml"),
        format!("[ports.web]\nport = {preferred}\nenv = \"PORT\"\nreason = \"Web server\"\n")
            .replace("\\\"", "\""),
    )
    .unwrap();
    git(&fixture.repo, &["add", ".shoal.toml"]);
    git(
        &fixture.repo,
        &[
            "-c",
            "user.name=Test",
            "-c",
            "user.email=test@example.invalid",
            "commit",
            "-m",
            "config",
        ],
    );
    let workspace = fixture.add("configured");
    let path = Path::new(workspace["path"].as_str().unwrap());
    let overview = fixture
        .command()
        .current_dir(path)
        .args(["--json", "leases", "port"])
        .output()
        .unwrap();
    assert!(overview.status.success());
    let overview: Value = serde_json::from_slice(&overview.stdout).unwrap();
    assert_eq!(overview["reserved"], serde_json::json!([]));
    assert_eq!(
        fixture.ok(&["leases", "port", "--workspace", "configured"]),
        overview
    );
    let catalog = fixture
        .command()
        .current_dir(path)
        .args(["--json", "catalog", "port"])
        .output()
        .unwrap();
    assert!(catalog.status.success());
    let catalog: Value = serde_json::from_slice(&catalog.stdout).unwrap();
    assert_eq!(catalog["configured"]["web"]["port"], preferred);
    let proposal = fixture.run(&[
        "--json",
        "acquire",
        "port",
        "web",
        "--workspace",
        "configured",
    ]);
    assert_eq!(proposal.status.code(), Some(2));
    let proposal: Value = serde_json::from_slice(&proposal.stdout).unwrap();
    assert_eq!(proposal["reserved"], false);
    assert_eq!(
        fixture.ok(&["leases", "port", "--workspace", "configured"])["reserved"],
        serde_json::json!([])
    );
    let accepted = fixture.ok(&[
        "acquire",
        "port",
        "web",
        "--workspace",
        "configured",
        "--port",
        &proposal["suggested_port"].to_string(),
    ]);
    assert_eq!(accepted["env_var"], "PORT");
    assert_eq!(
        fixture.ok(&["acquire", "port", "web", "--workspace", "configured"]),
        accepted
    );
    fixture.ok(&["release", "port", "web", "--workspace", "configured"]);
    let automatic = fixture.ok(&[
        "acquire",
        "port",
        "web",
        "--workspace",
        "configured",
        "--on-conflict",
        "auto",
    ]);
    assert_ne!(automatic["port"], preferred);
    assert_eq!(
        fixture.ok(&["acquire", "port", "web", "--workspace", "configured"]),
        automatic
    );
    fs::create_dir(path.join(".shoal")).unwrap();
    fs::rename(path.join(".shoal.toml"), path.join(".shoal/config.toml")).unwrap();
    fixture.ok(&["catalog", "port", "--workspace", "configured"]);
    // Both together are rejected, so neither names the port, and the
    // workspace's config says why.
    fs::write(path.join(".shoal.toml"), "").unwrap();
    let catalog = fixture.ok(&["catalog", "port", "--workspace", "configured"]);
    assert!(catalog["configured"].get("web").is_none(), "{catalog}");
    let show = fixture.run(&["config", "show", "configured"]);
    assert!(show.status.success());
    let warning = String::from_utf8(show.stderr).unwrap();
    assert!(
        warning.contains("keep only one repository config"),
        "{warning}"
    );
}

#[test]
fn execution_scope_limits_management_and_expires() {
    let fixture = Fixture::new();
    let setup = fixture.repo.join("setup.sh");
    install_test_script(&setup, "#!/bin/sh\nprintf setup >> setup-runs\n");
    let post_setup = fixture.repo.join("post-setup.sh");
    install_test_script(
        &post_setup,
        "#!/bin/sh\ntest -z \"$SHOAL_SCOPE_TOKEN\" || exit 81\ntest -z \"$SHOAL_EXECUTION_ID\" || exit 82\ntest -z \"$SHOAL_RESERVED_PORT_ENV\" || exit 83\ntest -z \"$SHOAL_PORT_WEB\" || exit 84\ntest -z \"$SHOAL_OUTPUT\" || exit 85\nprintf hook >> hook-runs\npython3 -c 'import time; time.sleep(30)' < /dev/null > /dev/null 2>&1 &\n",
    );
    commit_resource_config(
        &fixture.repo,
        "setup.command = 'setup.sh'\nhooks.post_setup = 'post-setup.sh'\n",
    );
    let worker = fixture.add("worker");
    let worker_path = Path::new(worker["path"].as_str().unwrap());
    fixture.add("other");
    let binary = support::shoal_binary();
    let scoped = |args: &[&str]| {
        fixture
            .command()
            .args(["run", "--workspace", "worker", "--", binary])
            .args(args)
            .output()
            .unwrap()
    };
    let output = scoped(&["--json", "work"]);
    assert!(output.status.success());
    let list: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(list.as_array().unwrap().len(), 1);
    assert_eq!(list[0]["name"], "worker");
    let output = scoped(&["--json", "config", "show"]);
    assert!(output.status.success(), "{output:?}");
    let config: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert!(
        config
            .as_array()
            .unwrap()
            .iter()
            .any(|entry| { entry["key"] == "setup.command" && entry["value"] == "setup.sh" })
    );
    assert!(scoped(&["acquire", "port", "web"]).status.success());
    let sibling_started = worker_path.join("sibling-started");
    let mut sibling = fixture
        .command()
        .args([
            "run",
            "--workspace",
            "worker",
            "--",
            "sh",
            "-c",
            "touch sibling-started; sleep 30",
        ])
        .spawn()
        .unwrap();
    wait_until("sibling execution", || sibling_started.exists());
    let output = scoped(&["work", "setup", "worker"]);
    assert!(!output.status.success(), "{output:?}");
    fixture.ok(&["stop", "worker"]);
    assert!(!sibling.wait().unwrap().success());
    // An agent's output default does not reach the hook its setup runs.
    let output = fixture
        .command()
        .env("SHOAL_OUTPUT", "json")
        .args(["run", "--workspace", "worker", "--", binary])
        .args(["work", "setup", "worker"])
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(
        fs::read_to_string(worker_path.join("setup-runs")).unwrap(),
        "setupsetup"
    );
    assert_eq!(
        fs::read_to_string(worker_path.join("hook-runs")).unwrap(),
        "hookhook"
    );
    assert_eq!(
        fixture.ok(&["work", "status", "worker"])["executions"],
        serde_json::json!([]),
        "hook survivors must not belong to the invoking execution"
    );
    assert!(
        scoped(&[
            "run",
            "--workspace",
            "worker",
            "--",
            binary,
            "leases",
            "port"
        ])
        .status
        .success()
    );
    for args in [
        vec!["rm", "worker", "--yes"],
        vec!["stop", "worker"],
        vec!["work", "status", "other"],
        vec!["run", "--workspace", "other", "--", "true"],
        vec!["work", "setup", "other"],
        vec!["link", "pr", "42", "assigned", "--space", "other"],
        vec!["unlink", "pr", "assigned", "--space", "other"],
        vec!["done", "--undo", "other"],
        vec!["done", "other", "--cleanup"],
        vec!["config", "show", "other"],
        vec![
            "config",
            "set",
            "agent.default",
            "codex",
            "--repo",
            fixture.repo.to_str().unwrap(),
        ],
        vec![
            "config",
            "unset",
            "agent.default",
            "--repo",
            fixture.repo.to_str().unwrap(),
        ],
        vec!["acquire", "port", "web", "--workspace", "other"],
        vec!["repo", "rename", fixture.repo.to_str().unwrap(), "changed"],
        vec!["repo", "config", fixture.repo.to_str().unwrap()],
        vec!["daemon", "stop"],
    ] {
        let output = scoped(&args);
        assert!(
            !output.status.success(),
            "scoped {args:?} unexpectedly succeeded"
        );
    }
    let token = fixture.run(&[
        "run",
        "--workspace",
        "worker",
        "--",
        "sh",
        "-c",
        "printf '%s' \"$SHOAL_SCOPE_TOKEN\"",
    ]);
    let token = String::from_utf8(token.stdout).unwrap();
    assert!(!token.is_empty());
    let output = fixture
        .command()
        .env("SHOAL_SCOPE_TOKEN", token)
        .args(["work"])
        .output()
        .unwrap();
    assert!(!output.status.success());
    assert_eq!(fixture.ok(&["work"]).as_array().unwrap().len(), 2);
}

