#[test]
fn setup_continues_after_the_cli_that_started_it_exits() {
    let fixture = Fixture::new();
    let release = fixture.root.path().join("release-setup");
    install_test_script(
        fixture.repo.join("setup.sh"),
        format!(
            "#!/bin/sh\necho preparing\ntouch setup-started\nwhile [ ! -e '{}' ]; do sleep 0.1; done\ntouch setup-finished\n",
            release.display()
        ),
    );
    install_test_script(
        fixture.repo.join("post-setup.sh"),
        "#!/bin/sh\ntouch post-setup-ran\n",
    );
    commit_resource_config(
        &fixture.repo,
        "setup.command = 'setup.sh'\nhooks.post_setup = 'post-setup.sh'\n",
    );
    let repo = fixture.repo.to_str().unwrap();
    // The CLI shows what setup writes, as it did when it ran setup itself.
    fs::write(&release, "").unwrap();
    let output = fixture.run(&["--json", "start", repo, "quick"]);
    assert!(output.status.success(), "{output:?}");
    assert!(
        String::from_utf8_lossy(&output.stderr).contains("preparing"),
        "{output:?}"
    );
    fs::remove_file(&release).unwrap();
    let mut add = fixture
        .command()
        .args(["--json", "start", repo, "slow"])
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    let path = wait_for("the slow workspace", || {
        let listed = fixture.ok(&["work"]);
        let slow = listed.as_array()?.iter().find(|w| w["name"] == "slow")?;
        Some(PathBuf::from(slow["path"].as_str()?))
    });
    wait_until("setup to start", || path.join("setup-started").exists());
    add.kill().unwrap();
    add.wait().unwrap();
    fs::write(&release, "").unwrap();
    // The post-setup hook runs with setup, so it runs without the CLI too.
    wait_until("the post-setup hook to run", || {
        path.join("post-setup-ran").exists()
    });
    assert!(path.join("setup-finished").exists());
    assert_eq!(
        fixture.ok(&["work", "status", "slow"])["workspace"]["state"],
        "ready"
    );
}

#[test]
fn an_operation_keeps_its_scope_after_the_execution_that_started_it_ends() {
    let fixture = Fixture::new();
    let release = fixture.root.path().join("release-setup");
    install_test_script(
        fixture.repo.join("setup.sh"),
        format!(
            "#!/bin/sh\ntouch setup-started\nwhile [ ! -e '{}' ]; do sleep 0.1; done\n",
            release.display()
        ),
    );
    install_test_script(
        fixture.repo.join("post-setup.sh"),
        "#!/bin/sh\ntouch post-setup-ran\n",
    );
    commit_resource_config(
        &fixture.repo,
        "setup.command = 'setup.sh'\nhooks.post_setup = 'post-setup.sh'\n",
    );
    fs::write(&release, "").unwrap();
    let worker = fixture.add("worker");
    let path = PathBuf::from(worker["path"].as_str().unwrap());
    fs::remove_file(&release).unwrap();
    fs::remove_file(path.join("setup-started")).unwrap();
    fs::remove_file(path.join("post-setup-ran")).unwrap();
    // A scoped command reruns setup, drops its CLI and ends normally, so its
    // execution's end stops whatever still carries its identity.
    let command = format!(
        "'{}' work setup worker >/dev/null 2>&1 & cli=$!; while [ ! -e '{}' ]; do sleep 0.1; done; kill -9 $cli",
        support::shoal_binary(),
        path.join("setup-started").display()
    );
    let output = fixture.run(&["run", "--workspace", "worker", "--", "sh", "-c", &command]);
    assert!(output.status.success(), "{output:?}");
    fs::write(&release, "").unwrap();
    wait_until("the post-setup hook to run", || {
        path.join("post-setup-ran").exists()
    });
}

#[test]
fn interrupting_the_cli_during_the_pre_setup_hook_stops_setup_as_it_starts() {
    let fixture = Fixture::new();
    let started = fixture.root.path().join("pre-setup-started");
    let release = fixture.root.path().join("release-pre-setup");
    install_test_script(
        fixture.repo.join("pre-setup.sh"),
        format!(
            "#!/bin/sh\ntouch '{}'\nwhile [ ! -e '{}' ]; do sleep 0.1; done\n",
            started.display(),
            release.display()
        ),
    );
    // Setup that ran on would outlast every wait below.
    install_test_script(
        fixture.repo.join("setup.sh"),
        "#!/bin/sh\nexec python3 -c 'import time; time.sleep(600)'\n",
    );
    commit_resource_config(
        &fixture.repo,
        "setup.command = 'setup.sh'\nhooks.pre_setup = 'pre-setup.sh'\n",
    );
    let mut add = fixture
        .command()
        .args(["--json", "start", fixture.repo.to_str().unwrap(), "gated"])
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    let stderr = lines(add.stderr.take().unwrap());
    wait_until("the pre-setup hook to start", || started.exists());
    assert_eq!(unsafe { libc::kill(add.id() as i32, libc::SIGTERM) }, 0);
    // The worker says so once it is cancelled, before its setup listens for
    // signals.
    wait_until("the cancel to reach the worker", || {
        stderr
            .try_iter()
            .any(|line| line == "Operation cancelled; stopping its work")
    });
    fs::write(&release, "").unwrap();
    let status = wait_for("the CLI to stop", || add.try_wait().unwrap());
    assert!(!status.success());
    let status = fixture.ok(&["work", "status", "gated"]);
    assert_eq!(status["workspace"]["state"], "failed");
    assert_eq!(status["executions"], serde_json::json!([]));
}

#[test]
fn interrupting_the_cli_stops_the_post_setup_hook_and_what_ignores_sigterm_below_it() {
    let fixture = Fixture::new();
    let pid_file = fixture.root.path().join("hook.pid");
    // The hook exits on SIGTERM; what it started does not.
    install_test_script(
        fixture.repo.join("post-setup.sh"),
        format!(
            "#!/bin/sh\nsh -c 'trap \"\" TERM; echo $$ > \"$0\"; exec python3 -c \"import time; time.sleep(60)\"' '{}' &\nwait\n",
            pid_file.display()
        ),
    );
    commit_resource_config(&fixture.repo, "hooks.post_setup = 'post-setup.sh'\n");
    let mut add = fixture
        .command()
        .args(["--json", "start", fixture.repo.to_str().unwrap(), "hooked"])
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    let pid: u32 = wait_for("the hook to start", || {
        fs::read_to_string(&pid_file).ok()?.trim().parse().ok()
    });
    assert_eq!(unsafe { libc::kill(add.id() as i32, libc::SIGTERM) }, 0);
    let status = wait_for("the CLI to stop", || add.try_wait().unwrap());
    assert!(!status.success());
    wait_until("what the hook started to stop", || !process_running(pid));
    assert_eq!(
        fixture.ok(&["work", "status", "hooked"])["workspace"]["state"],
        "ready"
    );
}

/// The lines `stream` carries, as a reader thread receives them.
fn lines(stream: impl std::io::Read + Send + 'static) -> std::sync::mpsc::Receiver<String> {
    let (send, receive) = std::sync::mpsc::channel();
    thread::spawn(move || {
        for line in std::io::BufRead::lines(std::io::BufReader::new(stream)).map_while(Result::ok) {
            if send.send(line).is_err() {
                break;
            }
        }
    });
    receive
}

#[cfg(target_os = "macos")]
const SIM_CONFIG: &str = r#"
[machine.simulators]
max_booted = 1
max_devices = 2
idle_seconds = 120
default = "phone"
[machine.simulators.profiles.phone]
device = "Phone"
runtime = "iOS Test"
[machine.simulators.profiles.tablet]
device = "Tablet"
runtime = "iOS Test"
"#;

#[test]
#[cfg(target_os = "macos")]
fn simulator_omitted_runtime_uses_latest_ios_and_preserves_existing_lease() {
    let config = SIM_CONFIG.replace("runtime = \"iOS Test\"", "");
    let fixture = Fixture::with_tools(Some(&config), true);
    let set_runtimes = |newer_available| {
        fs::write(
            fixture.root.path().join("sim-runtimes.json"),
            serde_json::json!([
                {"name": "iOS 26.9", "identifier": "com.apple.CoreSimulator.SimRuntime.iOS-26-9", "version": "26.9", "isAvailable": true},
                {"name": "iOS 26.10", "identifier": "com.apple.CoreSimulator.SimRuntime.iOS-26-10", "version": "26.10", "isAvailable": true},
                {"name": "iOS 27", "identifier": "com.apple.CoreSimulator.SimRuntime.iOS-27-0", "version": "27.0", "isAvailable": newer_available},
                {"name": "tvOS 28", "identifier": "com.apple.CoreSimulator.SimRuntime.tvOS-28-0", "version": "28.0", "isAvailable": true}
            ]).to_string(),
        ).unwrap();
    };
    set_runtimes(false);
    fixture.add("worker");
    let first = fixture.ok(&["acquire", "sim", "--workspace", "worker"]);
    assert_eq!(
        first["runtime"],
        "com.apple.CoreSimulator.SimRuntime.iOS-26-10"
    );
    set_runtimes(true);
    assert_eq!(
        fixture.ok(&["acquire", "sim", "--workspace", "worker"]),
        first
    );
    assert_eq!(
        fixture.ok(&[
            "acquire",
            "sim",
            "--workspace",
            "worker",
            "--device",
            "Phone"
        ]),
        first
    );
    assert_eq!(
        fixture.ok(&[
            "acquire",
            "sim",
            "--workspace",
            "worker",
            "--profile",
            "phone"
        ]),
        first
    );
    fixture.ok(&[
        "release",
        "sim",
        "--name",
        "default",
        "--workspace",
        "worker",
    ]);
    let next = fixture.ok(&[
        "acquire",
        "sim",
        "--workspace",
        "worker",
        "--device",
        "Phone",
    ]);
    assert_eq!(
        next["runtime"],
        "com.apple.CoreSimulator.SimRuntime.iOS-27-0"
    );
    let events = fs::read_to_string(fixture.root.path().join("sim-events")).unwrap();
    let creates: Vec<Value> = events
        .lines()
        .map(|line| serde_json::from_str::<Value>(line).unwrap())
        .filter(|event| event[0] == "create")
        .collect();
    assert_eq!(creates.len(), 2);
    assert_eq!(creates[0][3], first["runtime"]);
    assert_eq!(creates[1][3], next["runtime"]);
}

#[test]
fn the_daemon_alerts_about_global_config_problems_on_start_and_reload() {
    let environment = |fixture: &Fixture| -> Vec<String> {
        fixture
            .ok(&["alerts", "--all", "--keep-unread"])
            .as_array()
            .unwrap()
            .iter()
            .filter(|event| event["kind"] == "environment_problem")
            .map(|event| event["message"].as_str().unwrap().to_owned())
            .collect()
    };
    let reported = |fixture: &Fixture, setting: &str| {
        environment(fixture)
            .iter()
            .any(|message| message.contains(setting))
    };
    let fixture = Fixture::with_config(Some(
        "rules.worker.text = 'You are working in Shoal workspace {workspace} on branch {branch} at {path}.'\n",
    ));
    // The startup check reads the config before it records its alerts, so
    // this one shows it is past reading by the time the config changes.
    wait_until("the startup environment alert", || {
        reported(&fixture, "rules.worker.text")
    });
    // A problem added later is reported only by the reload. A root inside a
    // file cannot be created.
    let root_file = tempfile::NamedTempFile::new().unwrap();
    fs::write(
        fixture.root.path().join(".config/shoal/config.toml"),
        format!(
            "machine.root_dir = {:?}\n",
            root_file.path().join("repos").to_str().unwrap()
        ),
    )
    .unwrap();
    assert!(!reported(&fixture, "root_dir"));
    fixture.ok(&["daemon", "reload"]);
    wait_until("the reload environment alert", || {
        reported(&fixture, "root_dir")
    });
}

#[test]
#[cfg(target_os = "macos")]
fn global_config_changes_reload_a_running_daemon() {
    let fixture = Fixture::with_tools(None, true);
    fixture.add("worker");
    let policy = || fixture.ok(&["catalog", "sim", "--workspace", "worker"])["policy"].clone();
    assert!(policy()["default"].is_null());
    let result = fixture.ok(&[
        "config",
        "set",
        "machine.simulators.profiles.phone.device",
        "iPhone 17",
        "machine.simulators.profiles.phone.runtime",
        "iOS 27",
        "machine.simulators.default",
        "phone",
    ]);
    assert_eq!(result["daemon_reloaded"], true);
    assert_eq!(policy()["default"], "phone");
    let catalog = fixture.ok(&["catalog", "--workspace", "worker"]);
    assert_eq!(catalog["simulators"]["policy"], policy());
    // Hand edits apply on an explicit reload; an invalid file keeps the running config.
    let config = fixture.root.path().join(".config/shoal/config.toml");
    let edited = fs::read_to_string(&config).unwrap();
    fs::write(
        &config,
        format!("{edited}\n[machine.simulators]\nmax_booted = 0\n"),
    )
    .unwrap();
    assert!(!fixture.run(&["daemon", "reload"]).status.success());
    assert_eq!(policy()["default"], "phone");
    fs::write(
        &config,
        format!("{NO_GRACE}{UNSETTLED}{FORGEJO_HOST}{NO_OVERLOAD_WARNINGS}"),
    )
    .unwrap();
    assert!(fixture.run(&["daemon", "reload"]).status.success());
    assert!(policy()["default"].is_null());
}

#[test]
#[cfg(target_os = "macos")]
fn simulator_exclusivity_wait_reuse_scope_and_removal() {
    let fixture = Fixture::with_tools(Some(SIM_CONFIG), true);
    fixture.add("first");
    fixture.add("second");
    let first = fixture.ok(&["acquire", "sim", "--workspace", "first"]);
    assert_eq!(first["state"], "leased");
    assert_eq!(
        fixture.ok(&["work", "status", "first"])["simulators"][0],
        first
    );
    assert_eq!(
        fixture.ok(&["acquire", "sim", "--workspace", "first"]),
        first
    );
    let busy = fixture.run(&["--json", "acquire", "sim", "--workspace", "second"]);
    assert_eq!(busy.status.code(), Some(2));
    assert_eq!(
        serde_json::from_slice::<Value>(&busy.stdout).unwrap()["acquired"],
        false
    );
    fixture.ok(&["alerts"]);
    let mut waiting = fixture
        .command()
        .args([
            "--json",
            "acquire",
            "sim",
            "--workspace",
            "second",
            "--queue",
        ])
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    wait_for_busy(&fixture, "second");
    assert!(waiting.try_wait().unwrap().is_none());
    fixture.ok(&[
        "release",
        "sim",
        "--name",
        "default",
        "--workspace",
        "first",
    ]);
    assert_eq!(
        fixture.ok(&["work", "status", "first"])["simulators"],
        serde_json::json!([])
    );
    let second = waiting.wait_with_output().unwrap();
    assert!(second.status.success());
    let second: Value = serde_json::from_slice(&second.stdout).unwrap();
    assert_eq!(second["udid"], first["udid"]);
    let events = fs::read_to_string(fixture.root.path().join("sim-events")).unwrap();
    assert!(
        !events.contains("erase") && !events.contains("shutdown"),
        "normal handoff must preserve simulator state without rebooting"
    );
    let scoped = fixture.run(&[
        "run",
        "--workspace",
        "first",
        "--",
        support::shoal_binary(),
        "release",
        "sim",
        "--name",
        "default",
        "--workspace",
        "second",
    ]);
    assert!(!scoped.status.success());
    let listed = fixture.run(&[
        "run",
        "--workspace",
        "first",
        "--",
        support::shoal_binary(),
        "--json",
        "leases",
        "sim",
        "--all",
    ]);
    assert_eq!(
        serde_json::from_slice::<Value>(&listed.stdout).unwrap()["simulators"],
        serde_json::json!([])
    );
    fixture.ok(&["rm", "first"]);
    assert_eq!(
        fixture.ok(&["leases", "sim", "--all"])["simulators"]
            .as_array()
            .unwrap()
            .len(),
        1
    );
    fixture.ok(&["rm", "second"]);
    assert_eq!(
        fixture.ok(&["leases", "sim", "--all"])["simulators"],
        serde_json::json!([])
    );
    assert_eq!(
        fs::read_to_string(fixture.root.path().join("sim-devices.json")).unwrap(),
        "[]"
    );
}

#[test]
#[cfg(target_os = "macos")]
fn simulator_leases_journal_acquisition_and_release() {
    let fixture = Fixture::with_tools(Some(SIM_CONFIG), true);
    fixture.add("first");
    let sim = fixture.ok(&["acquire", "sim", "--workspace", "first"]);
    fixture.ok(&["acquire", "sim", "--workspace", "first"]);
    fixture.ok(&["release", "sim", "--workspace", "first"]);
    fixture.ok(&["acquire", "sim", "--workspace", "first"]);
    // Removal deletes the leased device, which releases the lease.
    fixture.ok(&["rm", "first"]);
    let events: Vec<_> = journal(&fixture)
        .into_iter()
        .filter(|event| event["simulator"].is_object())
        .collect();
    assert_eq!(
        events
            .iter()
            .map(|event| event["kind"].as_str().unwrap_or_default())
            .collect::<Vec<_>>(),
        [
            "simulator_acquired",
            "simulator_released",
            "simulator_acquired",
            "simulator_released"
        ]
    );
    for event in &events {
        assert_eq!(event["name"], "first");
        assert_eq!(event["simulator"]["name"], "default");
        assert_eq!(event["simulator"]["udid"], sim["udid"]);
        assert_eq!(event["simulator"]["device"], sim["device"]);
    }
}

#[test]
#[cfg(target_os = "macos")]
fn simulator_failures_retain_claims_and_restart_never_reassigns_them() {
    let mut fixture = Fixture::with_tools(Some(SIM_CONFIG), true);
    fixture.add("first");
    fixture.add("second");
    fs::write(fixture.root.path().join("sim-fail"), "bootstatus").unwrap();
    assert!(
        !fixture
            .run(&["acquire", "sim", "--workspace", "first"])
            .status
            .success()
    );
    assert_eq!(
        fixture.ok(&["leases", "sim", "--workspace", "first"])["simulators"][0]["state"],
        "failed"
    );
    fs::remove_file(fixture.root.path().join("sim-fail")).unwrap();
    fixture.ok(&[
        "release",
        "sim",
        "--name",
        "default",
        "--workspace",
        "first",
    ]);
    let lease = fixture.ok(&["acquire", "sim", "--workspace", "first"]);
    fixture.daemon.kill();
    fixture.restart();
    assert_eq!(
        fixture.ok(&["acquire", "sim", "--workspace", "first"]),
        lease
    );
    assert_eq!(
        fixture
            .run(&["acquire", "sim", "--workspace", "second"])
            .status
            .code(),
        Some(2)
    );
    fs::write(fixture.root.path().join("sim-fail"), "delete").unwrap();
    assert!(!fixture.run(&["rm", "first"]).status.success());
    assert_eq!(
        fixture.ok(&["leases", "sim", "--workspace", "first"])["simulators"][0]["udid"],
        lease["udid"]
    );
    fs::remove_file(fixture.root.path().join("sim-fail")).unwrap();
    fixture.ok(&["rm", "first"]);
    assert_eq!(
        fixture.ok(&["leases", "sim", "--all"])["simulators"],
        serde_json::json!([])
    );
}

#[test]
#[cfg(target_os = "macos")]
fn simulator_requires_confirmed_native_boot_and_shutdown_states() {
    let fixture = Fixture::with_tools(Some(SIM_CONFIG), true);
    fixture.add("worker");
    let overrides = fixture.root.path().join("sim-state-overrides.json");
    for native in ["Creating", "Booting", "Shutting Down", "Future State"] {
        fs::write(
            &overrides,
            serde_json::json!({"bootstatus": native}).to_string(),
        )
        .unwrap();
        let output = fixture.run(&["acquire", "sim", "--workspace", "worker"]);
        assert!(!output.status.success());
        let failed =
            fixture.ok(&["leases", "sim", "--workspace", "worker"])["simulators"][0].clone();
        assert_eq!(failed["state"], "failed");

        fs::write(
            &overrides,
            serde_json::json!({"shutdown": native}).to_string(),
        )
        .unwrap();
        let output = fixture.run(&[
            "release",
            "sim",
            "--name",
            "default",
            "--workspace",
            "worker",
        ]);
        assert!(!output.status.success());
        assert_eq!(
            fixture.ok(&["leases", "sim", "--workspace", "worker"])["simulators"][0]["udid"],
            failed["udid"]
        );
        let events = fs::read_to_string(fixture.root.path().join("sim-events")).unwrap();
        assert!(!events.contains(&format!("[\"delete\", {}]", failed["udid"])));
        fs::remove_file(&overrides).unwrap();
        fixture.ok(&[
            "release",
            "sim",
            "--name",
            "default",
            "--workspace",
            "worker",
        ]);
    }

    let lease = fixture.ok(&["acquire", "sim", "--workspace", "worker"]);
    let devices_path = fixture.root.path().join("sim-devices.json");
    let mut devices: Value =
        serde_json::from_str(&fs::read_to_string(&devices_path).unwrap()).unwrap();
    for native in ["Shutdown", "Booting", "Shutting Down", "Future State"] {
        devices[0]["state"] = serde_json::json!(native);
        fs::write(&devices_path, devices.to_string()).unwrap();
        let output = fixture.run(&["acquire", "sim", "--workspace", "worker"]);
        assert!(!output.status.success());
        assert_eq!(
            fixture.ok(&["leases", "sim", "--workspace", "worker"])["simulators"][0],
            lease
        );
    }
    devices[0]["state"] = serde_json::json!("Booted");
    fs::write(&devices_path, devices.to_string()).unwrap();
    assert_eq!(
        fixture.ok(&["acquire", "sim", "--workspace", "worker"]),
        lease
    );
}

#[test]
#[cfg(target_os = "macos")]
fn simulator_policy_capacity_reclamation_and_external_devices() {
    let fixture = Fixture::with_tools(Some(SIM_CONFIG), true);
    let workspace = fixture.add("worker");
    let path = Path::new(workspace["path"].as_str().unwrap());
    fs::write(
        path.join(".shoal.toml"),
        "[simulators]\npreferred = [\"tablet\"]\n",
    )
    .unwrap();
    let tablet = fixture.ok(&["acquire", "sim", "--workspace", "worker"]);
    assert_eq!(tablet["device"], "type.Tablet");
    fixture.ok(&[
        "release",
        "sim",
        "--name",
        "default",
        "--workspace",
        "worker",
    ]);
    let phone = fixture.ok(&[
        "acquire",
        "sim",
        "--workspace",
        "worker",
        "--profile",
        "phone",
    ]);
    assert_ne!(phone["udid"], tablet["udid"]);
    let devices: Value = serde_json::from_str(
        &fs::read_to_string(fixture.root.path().join("sim-devices.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        devices
            .as_array()
            .unwrap()
            .iter()
            .filter(|d| d["state"] == "Booted")
            .count(),
        1
    );
    fixture.ok(&[
        "release",
        "sim",
        "--name",
        "default",
        "--workspace",
        "worker",
    ]);
    let unavailable = fixture.run(&[
        "acquire",
        "sim",
        "--workspace",
        "worker",
        "--device",
        "Phone",
        "--runtime",
        "Missing",
    ]);
    assert!(!unavailable.status.success());
    let mut devices = devices.as_array().unwrap().clone();
    for device in &mut devices {
        device["state"] = serde_json::json!("Shutdown");
    }
    devices.push(serde_json::json!({"name":"Personal simulator","udid":"external","state":"Booted","isAvailable":true}));
    for native in [
        "Booted",
        "Creating",
        "Booting",
        "Shutting Down",
        "Future State",
    ] {
        devices.last_mut().unwrap()["state"] = serde_json::json!(native);
        fs::write(
            fixture.root.path().join("sim-devices.json"),
            serde_json::to_string(&devices).unwrap(),
        )
        .unwrap();
        assert_eq!(
            fixture
                .run(&["acquire", "sim", "--workspace", "worker"])
                .status
                .code(),
            Some(2),
            "external device in state {native} must occupy capacity"
        );
    }
    let events = fs::read_to_string(fixture.root.path().join("sim-events")).unwrap();
    assert!(!events.contains("external"));
    fixture.ok(&["rm", "worker", "--yes"]);
}

