#[test]
fn pre_setup_hook_gates_readiness_and_supports_global_defaults() {
    let fixture = Fixture::with_config(Some("hooks.pre_setup = 'before.sh'\n"));
    install_test_script(
        fixture.repo.join("before.sh"),
        r#"#!/bin/sh
set -eu
test "$SHOAL_HOOK" = pre_setup
test -z "${SHOAL_SCOPE_TOKEN:-}"
test -z "${SHOAL_EXECUTION_ID:-}"
echo before >> "$HOME/setup-order"
test ! -f "$HOME/fail-before" || { echo 'prepare failed' >&2; exit 7; }
"#,
    );
    install_test_script(
        fixture.repo.join("setup.sh"),
        "#!/bin/sh\necho setup >> \"$HOME/setup-order\"\n",
    );
    commit_resource_config(&fixture.repo, "setup.command = 'setup.sh'\n");
    let home = fixture.root.path();
    fs::write(home.join("fail-before"), "").unwrap();
    let output = fixture.run(&["start", fixture.repo.to_str().unwrap(), "hooked"]);
    assert!(!output.status.success());
    let inspection = fixture.ok(&["work", "status", "hooked"]);
    assert_eq!(inspection["workspace"]["state"], "failed");
    assert_eq!(inspection["executions"], serde_json::json!([]));
    assert_eq!(
        fs::read_to_string(home.join("setup-order")).unwrap(),
        "before\n"
    );
    fs::remove_file(home.join("fail-before")).unwrap();
    assert_eq!(fixture.ok(&["work", "setup", "hooked"])["state"], "ready");
    assert_eq!(
        fs::read_to_string(home.join("setup-order")).unwrap(),
        "before\nbefore\nsetup\n"
    );
    let path = Path::new(inspection["workspace"]["path"].as_str().unwrap());
    // A repository override wins; a pre-setup hook alone still gates readiness.
    fs::write(
        path.join(".shoal.toml"),
        "hooks.pre_setup = '/usr/bin/true'\n",
    )
    .unwrap();
    assert_eq!(fixture.ok(&["work", "setup", "hooked"])["state"], "ready");
    fs::write(fixture.repo.join(".shoal.toml"), "").unwrap();
    git(&fixture.repo, &["add", ".shoal.toml"]);
    git(
        &fixture.repo,
        &[
            "-c",
            "user.name=Shoal Test",
            "-c",
            "user.email=shoal@example.invalid",
            "commit",
            "-m",
            "hook only",
        ],
    );
    assert_eq!(fixture.add("hook-only")["state"], "ready");
    assert_eq!(
        fs::read_to_string(home.join("setup-order")).unwrap(),
        "before\nbefore\nsetup\nbefore\n"
    );
    fixture.ok(&["rm", "hooked", "--yes"]);
    fixture.ok(&["rm", "hook-only", "--yes"]);
}

#[test]
fn post_remove_hook_uses_checkout_and_reports_failure_after_removal() {
    let fixture = Fixture::with_config(Some(
        "hooks.post_remove = '/usr/bin/false'\n[env]\nPROFILE = '{workspace_path}/global-profile'\n",
    ));
    install_test_script(
        fixture.repo.join("after removal.sh"),
        r#"#!/bin/sh
set -eu
test "$SHOAL_HOOK" = post_remove
test -z "${SHOAL_SCOPE_TOKEN:-}"
test -z "${SHOAL_EXECUTION_ID:-}"
test ! -e "$SHOAL_WORKSPACE_PATH"
if [ "$SHOAL_WORKSPACE" = hooked ]; then
  test "$PROFILE" = "$SHOAL_WORKSPACE_PATH/saved-profile"
else
  test "$PROFILE" = "$SHOAL_WORKSPACE_PATH/global-profile"
fi
printf '%s\n%s\n%s\n' "$PWD" "$SHOAL_WORKSPACE" "$SHOAL_WORKSPACE_PATH" >> "$HOME/removed"
test ! -f "$HOME/fail-after" || { echo 'external cleanup failed' >&2; exit 8; }
"#,
    );
    commit_resource_config(
        &fixture.repo,
        "hooks.post_remove = 'after removal.sh'\n[resources.signing]\n",
    );
    let workspace = fixture.add("hooked");
    let path = Path::new(workspace["path"].as_str().unwrap());
    fixture.ok(&["acquire", "resource", "signing", "--workspace", "hooked"]);
    let config = path.join(".shoal.toml");
    fs::write(
        &config,
        "hooks.post_remove = 'after removal.sh'\nhooks.pre_remove = '/usr/bin/false'\n",
    )
    .unwrap();
    assert!(!fixture.run(&["rm", "hooked", "--yes"]).status.success());
    assert!(!fixture.root.path().join("removed").exists());
    fs::write(
        &config,
        "hooks.post_remove = 'after removal.sh'\n[env]\nPROFILE = '{workspace_path}/saved-profile'\n",
    )
    .unwrap();
    fs::write(fixture.root.path().join("fail-after"), "").unwrap();
    let result = fixture.ok(&["rm", "hooked", "--yes"]);
    assert_eq!(result["removed"], true);
    assert!(
        result["hook_error"]
            .as_str()
            .unwrap()
            .contains("external cleanup failed")
    );
    assert!(!fixture.run(&["work", "status", "hooked"]).status.success());
    let notifications = fixture.ok(&["alerts"]);
    assert!(
        notifications
            .as_array()
            .unwrap()
            .iter()
            .any(|n| n["kind"] == "hook_failed" && n["workspace"] == "hooked")
    );
    assert_eq!(
        fs::read_to_string(fixture.root.path().join("removed")).unwrap(),
        format!("{}\nhooked\n{}\n", fixture.repo.display(), path.display())
    );
    fs::remove_file(fixture.root.path().join("fail-after")).unwrap();
    fixture.add("next");
    fixture.ok(&["acquire", "resource", "signing", "--workspace", "next"]);
    let missing = fixture.add("missing");
    fs::remove_dir_all(missing["path"].as_str().unwrap()).unwrap();
    fixture.ok(&["rm", "missing", "--yes"]);
    assert_eq!(
        fs::read_to_string(fixture.root.path().join("removed"))
            .unwrap()
            .lines()
            .count(),
        3
    );
    // Repository removal invokes the hook before deleting its checkout.
    fixture.ok(&["repo", "rm", fixture.repo.to_str().unwrap(), "--yes"]);
    assert_eq!(
        fs::read_to_string(fixture.root.path().join("removed"))
            .unwrap()
            .lines()
            .count(),
        6
    );
}

#[test]
fn a_chats_alert_names_it_until_withdrawn() {
    let fixture = Fixture::new();
    let (mut agent, chat) = start_test_chat(&fixture, "planning");
    let in_chat = |args: &[&str]| {
        let output = fixture
            .command()
            .current_dir(&fixture.repo)
            .env("SHOAL_CHAT", &chat)
            .arg("--json")
            .args(args)
            .output()
            .unwrap();
        assert!(output.status.success(), "{args:?}: {output:?}");
        serde_json::from_slice::<Value>(&output.stdout).unwrap()
    };
    let sent = in_chat(&["alerts", "send", "Plan ready"]);
    let id = sent["notification"].as_i64().unwrap().to_string();
    let alerts = fixture.ok(&["alerts", "--keep-unread"]);
    let alert = alerts
        .as_array()
        .unwrap()
        .iter()
        .find(|alert| alert["message"] == "Plan ready")
        .unwrap_or_else(|| panic!("{alerts}"));
    assert_eq!(alert["workspace"], "planning", "{alert}");
    in_chat(&["alerts", "withdraw", &id]);
    let alerts = fixture.ok(&["alerts"]);
    assert!(
        alerts
            .as_array()
            .unwrap()
            .iter()
            .all(|alert| alert["message"] != "Plan ready"),
        "{alerts}"
    );
    agent.kill().unwrap();
    agent.wait().unwrap();
}

/// A chat's agent that changes into a workspace below the chat acts on that
/// workspace, as a workspace's agent acts on its child, and on the chat
/// anywhere else.
#[test]
fn a_chats_commands_act_on_the_workspace_below_it_whose_directory_they_run_in() {
    let fixture = Fixture::new();
    let (mut agent, chat) = start_test_chat(&fixture, "planning");
    let output = fixture
        .command()
        .args(["--json", "start", fixture.repo.to_str().unwrap(), "opened"])
        .env("SHOAL_CHAT", &chat)
        .stdin(Stdio::null())
        .output()
        .unwrap();
    assert!(output.status.success(), "{output:?}");
    let opened: Value = serde_json::from_slice(&output.stdout).unwrap();
    // A workspace that a chat below the chat opened is below it too.
    let mut nested_agent = support::isolated(fixture.root.path(), "sleep")
        .arg("600")
        .spawn()
        .unwrap();
    let repository = fixture.ok(&["repo", "ls"])[0]["id"].clone();
    let response = fixture.request(serde_json::json!({"start_chat":{
        "repository": repository, "name": "nested", "agent": "claude",
        "pid": nested_agent.id(), "parent": chat
    }}));
    let nested = response["data"]["id"].as_str().unwrap().to_owned();
    let output = fixture
        .command()
        .args(["--json", "start", fixture.repo.to_str().unwrap(), "deeper"])
        .env("SHOAL_CHAT", &nested)
        .stdin(Stdio::null())
        .output()
        .unwrap();
    assert!(output.status.success(), "{output:?}");
    let deeper: Value = serde_json::from_slice(&output.stdout).unwrap();
    let other = fixture.add("other");
    let rename_in = |directory: &Value, name: &str| {
        let output = fixture
            .command()
            .current_dir(directory.as_str().unwrap())
            .env("SHOAL_CHAT", &chat)
            .args(["--json", "work", "rename", name])
            .output()
            .unwrap();
        assert!(output.status.success(), "{output:?}");
        serde_json::from_slice::<Value>(&output.stdout).unwrap()["id"].clone()
    };

    let renamed = rename_in(&opened["path"], "Child work");
    assert_eq!(renamed, opened["id"]);
    let renamed = rename_in(&deeper["path"], "Nested work");
    assert_eq!(renamed, deeper["id"]);
    // A workspace not below the chat leaves the command to the chat.
    let renamed = rename_in(&other["path"], "replanning");
    assert_eq!(renamed, chat.as_str());
    assert_eq!(
        fixture.ok(&["work", "status", "other"])["workspace"]["title"],
        Value::Null
    );
    for agent in [&mut agent, &mut nested_agent] {
        agent.kill().unwrap();
        agent.wait().unwrap();
    }
}

#[test]
fn agents_notify_the_user_about_their_own_workspace_without_completing_it() {
    let fixture = Fixture::new();
    fixture.add("sender");
    fixture.add("other");
    let output = scoped_command(
        &fixture,
        "sender",
        &["alerts", "send", "PR #12 is ready to merge"],
    );
    assert!(output.status.success(), "{output:?}");
    // A message that stopped applying is withdrawn by the number alerts send gave.
    let output = scoped_command(&fixture, "sender", &["alerts", "send", "tests are failing"]);
    assert!(output.status.success(), "{output:?}");
    let sent: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    let id = sent["notification"].as_i64().unwrap().to_string();
    let output = scoped_command(&fixture, "sender", &["alerts", "withdraw", &id]);
    assert!(output.status.success(), "{output:?}");
    for args in [
        &["alerts", "withdraw", &id][..],
        &["alerts", "send", "hello", "--space", "other"][..],
        &["alerts", "send", "two\nlines"],
        &["alerts"],
    ] {
        let output = scoped_command(&fixture, "sender", args);
        assert!(
            !output.status.success(),
            "scoped {args:?} unexpectedly succeeded"
        );
    }
    let notifications = fixture.ok(&["alerts"]);
    let messages: Vec<_> = notifications
        .as_array()
        .unwrap()
        .iter()
        .filter(|notification| notification["kind"] == "agent_message")
        .map(|notification| (&notification["workspace"], &notification["message"]))
        .collect();
    assert_eq!(
        messages,
        [(
            &serde_json::json!("sender"),
            &serde_json::json!("PR #12 is ready to merge")
        )]
    );
    assert!(fixture.ok(&["work", "status", "sender"])["completion"].is_null());
}

#[test]
fn notifications_kept_unread_stay_new() {
    let fixture = Fixture::new();
    fixture.add("sender");
    for message in ["first", "second"] {
        let output = scoped_command(&fixture, "sender", &["alerts", "send", message]);
        assert!(output.status.success(), "{output:?}");
    }
    let unread = || fixture.ok(&["daemon", "status"])["daemon"]["unread_notifications"].clone();
    let messages = |notifications: &[Value]| -> Vec<(i64, String)> {
        notifications
            .iter()
            .filter(|notification| notification["kind"] == "agent_message")
            .map(|notification| {
                (
                    notification["id"].as_i64().unwrap(),
                    notification["message"].as_str().unwrap().to_owned(),
                )
            })
            .collect()
    };
    let before = unread();
    let listed = fixture.ok(&["alerts", "--keep-unread"]);
    let listed = messages(listed.as_array().unwrap());
    let texts: Vec<_> = listed.iter().map(|(_, text)| text.as_str()).collect();
    assert_eq!(texts, ["first", "second"]);
    assert_eq!(unread(), before);
    // A limited listing counts what it printed among the ones remaining.
    let limited = fixture.run(&["alerts", "--keep-unread", "--limit", "1"]);
    let remaining = before.as_u64().unwrap() - 1;
    let note = String::from_utf8_lossy(&limited.stderr);
    assert!(note.starts_with(&format!("{remaining} ")), "{note}");

    // A follower resuming after the first sees only the second, and keeps it unread.
    let mut follower = fixture
        .command()
        .args(["--json", "alerts", "--follow", "--keep-unread"])
        .args(["--resume", &listed[0].0.to_string()])
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    let stdout = follower.stdout.take().unwrap();
    let (sender, lines) = std::sync::mpsc::channel();
    thread::spawn(move || {
        use std::io::BufRead;
        for line in std::io::BufReader::new(stdout).lines() {
            if sender.send(line.unwrap()).is_err() {
                break;
            }
        }
    });
    let followed = loop {
        let line = lines
            .recv_timeout(Duration::from_secs(60))
            .expect("followed notification");
        let notification: Value = serde_json::from_str(&line).unwrap();
        if let [message] = &messages(&[notification])[..] {
            break message.clone();
        }
    };
    follower.kill().unwrap();
    follower.wait().unwrap();
    assert_eq!(followed, listed[1]);
    assert_eq!(unread(), before);

    let read = fixture.ok(&["alerts"]);
    assert_eq!(messages(read.as_array().unwrap()), listed);
    assert_eq!(fixture.ok(&["alerts"]), serde_json::json!([]));
}

#[test]
fn the_wake_hook_exits_with_its_agent() {
    let fixture = Fixture::new();
    let workspace = fixture.add("waking");
    let path = Path::new(workspace["path"].as_str().unwrap());
    // The sleep stands in for the agent; the hook would otherwise wait for an
    // update that never comes.
    let mut agent = Command::new("sleep").arg("600").spawn().unwrap();
    let mut hook = fixture
        .command()
        .current_dir(path)
        .args(["internal", "wake", "--agent", &agent.id().to_string()])
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    agent.kill().unwrap();
    agent.wait().unwrap();
    // A hang guard only: the hook checks its agent every second.
    wait_until("the wake hook to exit", || {
        hook.try_wait().unwrap().is_some()
    });
    let output = hook.wait_with_output().unwrap();
    assert_eq!(output.status.code(), Some(0));
    assert_eq!(String::from_utf8(output.stderr).unwrap(), "");
}

#[test]
fn a_chats_hooks_report_its_failed_turn_and_wake_it_for_its_messages() {
    let fixture = Fixture::new();
    let (mut agent, _) = start_test_chat(&fixture, "planning");

    // A failed turn reports for the chat, which keeps the session it names.
    let mut report = fixture
        .command()
        .current_dir(&fixture.repo)
        .args([
            "--json",
            "internal",
            "turn-failed",
            "--integration",
            "claude",
        ])
        .args(["--space", "planning"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    let event = r#"{"hook_event_name":"StopFailure","session_id":"failed-turn"}"#;
    let mut stdin = report.stdin.take().unwrap();
    stdin.write_all(event.as_bytes()).unwrap();
    drop(stdin);
    let output = report.wait_with_output().unwrap();
    assert!(output.status.success(), "{output:?}");
    let status: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(status["state"], "idle", "{status}");
    let chats = fixture.request(serde_json::json!("list_chats"));
    assert_eq!(chats["data"][0]["session"], "failed-turn", "{chats}");

    // The wake hook named the chat waits for its messages.
    let mut hook = fixture
        .command()
        .current_dir(&fixture.repo)
        .args(["internal", "wake", "--agent", &agent.id().to_string()])
        .args(["--space", "planning"])
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    let sent = fixture.request(serde_json::json!({"send_agent_message":{
        "space": "planning", "message": "Plan the next step"
    }}));
    assert_eq!(sent["type"], "ok", "{sent}");
    // A hang guard only: the message ends the wait.
    wait_until("the wake hook to exit", || {
        hook.try_wait().unwrap().is_some()
    });
    let output = hook.wait_with_output().unwrap();
    assert_eq!(output.status.code(), Some(2), "{output:?}");
    let woken = String::from_utf8(output.stderr).unwrap();
    assert!(woken.contains("Plan the next step"), "{woken}");
    agent.kill().unwrap();
    agent.wait().unwrap();
}

#[test]
fn a_title_request_reaches_only_a_running_agent() {
    let fixture = Fixture::new();
    fixture.add("titled");
    let output = fixture.run(&["work", "rename", "--request", "titled"]);
    assert!(!output.status.success());
    assert_eq!(fixture.ok(&["messages", "titled"]), serde_json::json!([]));

    // The agent runs until the test releases it.
    let bin = fixture.root.path().join("stub-bin");
    let (started, release) = (bin.join("started"), bin.join("release"));
    install_test_script_with_mode(
        bin.join("claude"),
        format!(
            "#!/bin/sh\ntouch '{}'\nwhile [ ! -e '{}' ]; do sleep 0.1; done\n",
            started.display(),
            release.display()
        ),
        0o700,
    );
    let mut agent = fixture
        .command()
        .args(["claude", "titled"])
        .env("PATH", fixture.restricted_path(&bin))
        .stdout(Stdio::null())
        .spawn()
        .unwrap();
    // The daemon tracks the agent before its wrapper starts it.
    wait_until("the agent to start", || started.exists());
    // An identical request the agent has not read yet collapses.
    for _ in 0..2 {
        fixture.ok(&["work", "rename", "--request", "titled"]);
    }
    let messages = fixture.ok(&["messages", "titled"]);
    assert_eq!(messages.as_array().unwrap().len(), 1, "{messages}");
    fs::write(&release, "").unwrap();
    assert!(agent.wait().unwrap().success());
}

#[test]
fn a_message_to_all_reaches_running_chats_but_not_workspaces_without_an_agent() {
    let fixture = Fixture::new();
    fixture.add("idle");
    let (mut agent, _) = start_test_chat(&fixture, "planning");
    let repo = fixture.repo.to_str().unwrap();
    let sent = fixture.ok(&["messages", "send", "--repo", repo, "Rebase onto main"]);
    assert_eq!(
        sent,
        serde_json::json!({
            "now": {"workspaces": [], "chats": ["planning"]},
            "on_start": {"workspaces": [], "chats": []}
        })
    );
    // A --repo without a value means the current repository.
    let output = fixture
        .command()
        .args(["--json", "messages", "send", "Pull main", "--repo"])
        .current_dir(&fixture.repo)
        .output()
        .unwrap();
    assert!(output.status.success(), "{output:?}");
    let sent: serde_json::Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(
        sent,
        serde_json::json!({
            "now": {"workspaces": [], "chats": ["planning"]},
            "on_start": {"workspaces": [], "chats": []}
        })
    );
    // --all reaches every repository, from outside any of them.
    let sent = fixture.ok(&["messages", "send", "--all", "The network works again"]);
    assert_eq!(
        sent,
        serde_json::json!({
            "now": {"workspaces": [], "chats": ["planning"]},
            "on_start": {"workspaces": [], "chats": []}
        })
    );
    assert_eq!(fixture.ok(&["messages", "idle"]), serde_json::json!([]));
    agent.kill().unwrap();
    agent.wait().unwrap();
    for conflicting in [["--all", "--space"], ["--all", "--repo"]] {
        let output = fixture.run(&[
            "messages",
            "send",
            conflicting[0],
            conflicting[1],
            "idle",
            "hi",
        ]);
        assert!(!output.status.success(), "{output:?}");
    }
}

#[test]
fn the_user_messages_agents_who_read_their_own_messages_once() {
    let fixture = Fixture::new();
    fixture.add("receiver");
    fixture.add("other");
    fixture.ok(&[
        "messages",
        "send",
        "Stop the dev server",
        "--space",
        "receiver",
    ]);
    let output = scoped_command(
        &fixture,
        "receiver",
        &["messages", "send", "hello", "--space", "receiver"],
    );
    assert!(!output.status.success(), "agents cannot send: {output:?}");
    let output = scoped_command(&fixture, "receiver", &["messages", "other"]);
    assert!(!output.status.success(), "{output:?}");
    let output = scoped_command(&fixture, "receiver", &["messages"]);
    assert!(output.status.success(), "{output:?}");
    let messages: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(messages[0]["message"], "Stop the dev server");
    assert_eq!(messages.as_array().unwrap().len(), 1);
    assert_eq!(fixture.ok(&["messages", "receiver"]), serde_json::json!([]));

    // Agent hooks print nothing without messages, then deliver new ones as
    // context for the event they answer.
    let hook = |stdin: &str| {
        let mut child = fixture
            .command()
            .args([
                "run",
                "--workspace",
                "receiver",
                "--",
                support::shoal_binary(),
            ])
            .args(["messages", "--hook"])
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .spawn()
            .unwrap();
        child
            .stdin
            .take()
            .unwrap()
            .write_all(stdin.as_bytes())
            .unwrap();
        let output = child.wait_with_output().unwrap();
        assert!(output.status.success(), "{output:?}");
        String::from_utf8(output.stdout).unwrap()
    };
    let event = r#"{"hook_event_name":"PostToolUse","tool_name":"Bash"}"#;
    assert_eq!(hook(event), "");
    fixture.ok(&["messages", "send", "Free disk space", "--space", "receiver"]);
    let output: Value = serde_json::from_str(&hook(event)).unwrap();
    let delivered = &output["hookSpecificOutput"];
    assert_eq!(delivered["hookEventName"], "PostToolUse", "{output}");
    assert!(
        delivered["additionalContext"]
            .as_str()
            .is_some_and(|context| context.contains("Free disk space")),
        "{output}"
    );
    assert_eq!(hook(event), "");
    // A message read from a file keeps its lines, indented under the first.
    let body = fixture.root.path().join("instructions.md");
    std::fs::write(&body, "Move commits:\n\tabc123 to api\n").unwrap();
    let body = body.to_str().unwrap();
    fixture.ok(&[
        "messages",
        "send",
        "--body-file",
        body,
        "--space",
        "receiver",
    ]);
    let output: Value = serde_json::from_str(&hook(event)).unwrap();
    let context = output["hookSpecificOutput"]["additionalContext"].as_str();
    assert!(
        context.is_some_and(|context| context.contains("Move commits:\n  \tabc123 to api")),
        "{output}"
    );

    // The wake hook prints the next update for the agent and exits 2, which
    // makes Claude Code start the idle agent's next turn with it. No hook
    // reports that turn starting, so the wake reports it working.
    fixture.ok(&[
        "messages",
        "send",
        "Rebase onto main",
        "--space",
        "receiver",
    ]);
    let output = fixture
        .command()
        .args(["run", "--workspace", "receiver", "--", "sh", "-c"])
        .arg(concat!(
            r#""$0" internal agent-state idle >/dev/null && "#,
            r#""$0" internal wake --agent "$1"; woke=$?; "#,
            r#""$0" work status --json && exit "$woke""#
        ))
        .arg(support::shoal_binary())
        .arg(std::process::id().to_string())
        .output()
        .unwrap();
    assert_eq!(output.status.code(), Some(2), "{output:?}");
    let woken = String::from_utf8(output.stderr).unwrap();
    assert!(woken.contains("Rebase onto main"), "{woken}");
    let status: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(
        status["workspace"]["agent_state"]["state"], "working",
        "{status}"
    );
    assert_eq!(hook(event), "");
}

#[test]
fn messages_carry_copies_of_attached_files() {
    let fixture = Fixture::new();
    fixture.add("receiver");
    fs::write(fixture.root.path().join("shot.png"), "image").unwrap();
    let output = fixture
        .command()
        .current_dir(fixture.root.path())
        .args([
            "messages",
            "send",
            "--attach",
            "shot.png#Login screen",
            "--space",
            "receiver",
        ])
        .output()
        .unwrap();
    assert!(output.status.success(), "{output:?}");
    fs::remove_file(fixture.root.path().join("shot.png")).unwrap();
    let messages = fixture.ok(&["messages", "receiver"]);
    assert_eq!(messages[0]["message"], "");
    let copy = Path::new(messages[0]["attachments"][0].as_str().unwrap());
    assert!(copy.starts_with(fixture.shoal_dir()), "{copy:?}");
    assert_eq!(fs::read_to_string(copy).unwrap(), "image");
    // The workspace's files list the copy after the message is read.
    let files = fixture.ok(&["files", "receiver"]);
    assert_eq!(files[0]["name"], "shot.png", "{files}");
    assert_eq!(files[0]["source"], "message", "{files}");
    assert_eq!(files[0]["title"], "Login screen", "{files}");
    assert_eq!(files[0]["path"], messages[0]["attachments"][0], "{files}");
    let paths = fixture.run(&["files", "receiver", "--path"]);
    assert_eq!(
        String::from_utf8(paths.stdout).unwrap().trim(),
        copy.display().to_string()
    );
}

/// Start a chat named `name` in the fixture's repository, whose agent the
/// returned sleep stands in for, and return it with the chat's ID.
fn start_test_chat(fixture: &Fixture, name: &str) -> (std::process::Child, String) {
    let repository = fixture.ok(&["repo", "ls"])[0].clone();
    let agent = support::isolated(fixture.root.path(), "sleep")
        .arg("600")
        .current_dir(fixture.root.path())
        .spawn()
        .unwrap();
    let response = fixture.request(serde_json::json!({"start_chat":{
        "repository": repository["id"], "name": name, "agent": "claude",
        "pid": agent.id()
    }}));
    assert_eq!(response["type"], "chat", "{response}");
    let chat = response["data"]["id"].as_str().unwrap().to_owned();
    (agent, chat)
}

/// Status names a chat in the namespace it shares with workspaces and
/// leaves out what needs a worktree; workspace processes see neither the
/// chat nor another workspace.
#[test]
fn status_shows_a_chat_without_the_parts_a_worktree_has() {
    let fixture = Fixture::new();
    let own = fixture.add("own");
    let (mut agent, chat) = start_test_chat(&fixture, "planning");

    let status = fixture.ok(&["work", "status", "planning"]);
    assert_eq!(status["kind"], "chat", "{status}");
    assert_eq!(status["chat"]["id"], chat.as_str(), "{status}");
    assert_eq!(status["sessions"], serde_json::json!([]), "{status}");
    for worktree in ["workspace", "executions", "ports", "diff", "cleanup_reason"] {
        assert_eq!(status.get(worktree), None, "{worktree}: {status}");
    }

    let status = fixture.ok(&["work", "status", "own"]);
    assert_eq!(status["kind"], "workspace", "{status}");
    assert_eq!(status["workspace"]["id"], own["id"], "{status}");
    assert_eq!(status["setup_finished"], true, "{status}");

    fixture.add("other");
    for other in ["planning", "other"] {
        let output = fixture.run(&[
            "run",
            "--workspace",
            "own",
            "--",
            support::shoal_binary(),
            "work",
            "status",
            other,
        ]);
        assert!(!output.status.success(), "{other}: {output:?}");
    }
    agent.kill().unwrap();
    agent.wait().unwrap();
}

#[test]
fn the_inbox_acts_on_a_chats_ready_row_as_a_chat() {
    let fixture = Fixture::new();
    let (mut agent, _) = start_test_chat(&fixture, "planning");
    fixture.ok(&["ready", "--space", "planning"]);
    // Presses $KEY on the first row whose ID starts with $PICK.
    install_test_script(
        fixture.root.path().join("bin/fzf"),
        r#"#!/bin/sh
cat > "$HOME/picker-input"
printf '%s\n' "$KEY"
awk -F '\t' -v pick="$PICK" 'index($1, pick) == 1 { print; exit }' "$HOME/picker-input"
"#,
    );
    let press = |key: &str| {
        let mut command = fixture.command();
        command.arg("inbox").env("PICK", "ready:").env("KEY", key);
        fixture.terminal_command(&mut command, "", true)
    };
    // Keys that act only on workspaces say so instead of failing to find one.
    let (output, transcript) = press("ctrl-o");
    assert!(!output.status.success(), "{transcript}");
    assert!(
        transcript.contains("this action acts only on workspaces"),
        "{transcript}"
    );
    // Viewing reads the chat's own links.
    let (output, transcript) = press("ctrl-v");
    assert!(!output.status.success(), "{transcript}");
    assert!(
        transcript.contains("the chat links no issue or PR"),
        "{transcript}"
    );
    // Enter attaches to the chat, whose agent says what is ready.
    let (_, transcript) = press("");
    assert!(!transcript.contains("unknown workspace"), "{transcript}");
    assert!(!transcript.contains("no workspace"), "{transcript}");
    agent.kill().unwrap();
    agent.wait().unwrap();
}

#[test]
fn a_chat_records_its_work_done_and_withdraws_it() {
    // Kept, so the chat stays to show its completion.
    let fixture = Fixture::with_config(Some("[cleanup.done]\nenabled = false\n"));
    let (mut agent, chat) = start_test_chat(&fixture, "planning");
    let report = fixture.root.path().join("report.md");
    fs::write(&report, "plan\n").unwrap();
    // The branch and demo options are a workspace's.
    for flag in ["--integrated", "--keep-demos"] {
        let output = fixture.run(&["done", "planning", flag]);
        assert!(!output.status.success(), "{flag}: {output:?}");
    }
    // Done again at the same HEAD with nothing new changes nothing.
    fixture.ok(&["done", "planning"]);
    let output = fixture.run(&["done", "planning"]);
    assert!(!output.status.success(), "{output:?}");
    let completion = fixture.ok(&["done", "planning", "--attach", report.to_str().unwrap()]);
    assert_eq!(completion["cleanup"], false, "{completion}");
    assert_eq!(
        completion["results"][0]["name"], "report.md",
        "{completion}"
    );
    // The chat keeps running, finished, and the user hears of it.
    let finished = fixture.ok(&["work", "--chats", "--status", "finished"]);
    assert!(finished.to_string().contains("planning"), "{finished}");
    let inbox = fixture.ok(&["inbox"]);
    assert_eq!(inbox[0]["kind"], "chat_done", "{inbox}");
    let alerts = fixture.ok(&["alerts"]);
    assert!(
        alerts
            .as_array()
            .unwrap()
            .iter()
            .any(|alert| { alert["kind"] == "workspace_done" && alert["workspace"] == "planning" }),
        "{alerts}"
    );
    // The user attached the report; the chat's agent attaches its own.
    let files = fixture.ok(&["files", "planning"]);
    assert_eq!(files[0]["name"], "report.md", "{files}");
    assert_eq!(files[0]["attached_by"]["kind"], "user", "{files}");
    let notes = fixture.root.path().join("notes.md");
    fs::write(&notes, "notes\n").unwrap();
    let output = fixture
        .command()
        .args(["--json", "done", "--attach", notes.to_str().unwrap()])
        .env("SHOAL_CHAT", &chat)
        .current_dir(&fixture.repo)
        .output()
        .unwrap();
    assert!(output.status.success(), "{output:?}");
    let files = fixture.ok(&["files", "planning"]);
    assert_eq!(files[1]["name"], "notes.md", "{files}");
    assert_eq!(files[1]["attached_by"]["kind"], "chat", "{files}");
    let completion: Value = serde_json::from_slice(&output.stdout).unwrap();
    let withdrawn = fixture.ok(&["done", "--undo", "planning"]);
    assert_eq!(withdrawn["withdrawn"]["results"], completion["results"]);
    let finished = fixture.ok(&["work", "--chats", "--status", "finished"]);
    assert!(!finished.to_string().contains("planning"), "{finished}");
    let output = fixture.run(&["done", "--undo", "planning"]);
    assert!(!output.status.success(), "{output:?}");
    agent.kill().unwrap();
    agent.wait().unwrap();
}

#[test]
fn completion_cleanup_removes_a_done_chat_with_the_workspaces_below_it() {
    let fixture = Fixture::new();
    let (mut agent, chat) = start_test_chat(&fixture, "planning");
    let output = fixture
        .command()
        .args(["--json", "start", fixture.repo.to_str().unwrap(), "opened"])
        .env("SHOAL_CHAT", &chat)
        .stdin(Stdio::null())
        .output()
        .unwrap();
    assert!(output.status.success(), "{output:?}");

    let completion = fixture.ok(&["done", "planning"]);
    assert_eq!(completion["cleanup"], true, "{completion}");
    // The user hears once the removal finished.
    wait_until("completion cleanup to remove the chat", || {
        let alerts = fixture.ok(&["alerts", "--all"]);
        alerts
            .as_array()
            .unwrap()
            .iter()
            .any(|alert| alert["kind"] == "workspace_removed" && alert["workspace"] == "planning")
    });
    assert_eq!(fixture.ok(&["work", "--chats"]), serde_json::json!([]));
    // The workspace below it went first, and its agent stopped.
    assert_eq!(fixture.ok(&["work"]), serde_json::json!([]));
    assert!(!agent.wait().unwrap().success());
}

#[test]
fn messages_reach_a_chat_with_their_files() {
    let fixture = Fixture::new();
    fixture.add("worker");
    let (mut agent, _) = start_test_chat(&fixture, "planning");
    // The user sends the chat a message with a file, which its inbox shows once.
    fs::write(fixture.root.path().join("shot.png"), "image").unwrap();
    let output = fixture
        .command()
        .current_dir(fixture.root.path())
        .args(["messages", "send", "Look at this", "--space", "planning"])
        .args(["--attach", "shot.png#Login screen"])
        .output()
        .unwrap();
    assert!(output.status.success(), "{output:?}");
    let messages = fixture.ok(&["messages", "planning"]);
    assert_eq!(messages[0]["message"], "Look at this", "{messages}");
    let copy = Path::new(messages[0]["attachments"][0].as_str().unwrap());
    assert_eq!(fs::read_to_string(copy).unwrap(), "image");
    let files = fixture.ok(&["files", "planning"]);
    assert_eq!(files[0]["source"], "message", "{files}");
    assert_eq!(fixture.ok(&["messages", "planning"]), serde_json::json!([]));
    // A workspace process cannot send to a chat.
    let output = scoped_command(
        &fixture,
        "worker",
        &["messages", "send", "hi", "--space", "planning"],
    );
    assert!(!output.status.success(), "{output:?}");
    agent.kill().unwrap();
    agent.wait().unwrap();
}

#[test]
fn files_add_attaches_copies_without_a_message() {
    let fixture = Fixture::new();
    fixture.add("receiver");
    fs::write(fixture.root.path().join("notes.md"), "plan").unwrap();
    let output = fixture
        .command()
        .current_dir(fixture.root.path())
        .args(["--json", "files", "add", "notes.md", "--space", "receiver"])
        .output()
        .unwrap();
    assert!(output.status.success(), "{output:?}");
    let added: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(added[0]["source"], "added", "{added}");
    assert!(added[0].get("title").is_none(), "{added}");
    let copy = Path::new(added[0]["path"].as_str().unwrap());
    assert_eq!(fs::read_to_string(copy).unwrap(), "plan");
    assert_eq!(fixture.ok(&["files", "receiver"]), added);
    // A title follows the path after #, and the list shows it.
    fs::write(fixture.root.path().join("chart.html"), "<svg/>").unwrap();
    let output = fixture
        .command()
        .current_dir(fixture.root.path())
        .args([
            "--json",
            "files",
            "add",
            "chart.html#Latency by region",
            "--space",
            "receiver",
        ])
        .output()
        .unwrap();
    assert!(output.status.success(), "{output:?}");
    let titled: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(titled[0]["name"], "chart.html", "{titled}");
    assert_eq!(titled[0]["title"], "Latency by region", "{titled}");
    let deleted = fixture.ok(&["files", "rm", "chart.html", "--space", "receiver"]);
    assert_eq!(deleted, titled);
    assert_eq!(fixture.ok(&["messages", "receiver"]), serde_json::json!([]));
    // A missing file fails before anything is picked or copied.
    let missing = fixture.run(&["files", "add", "missing.md", "--space", "receiver"]);
    assert!(!missing.status.success(), "{missing:?}");

    // An idle workspace's files go without asking; every workspace's only
    // once confirmed.
    let deleted = fixture.ok(&["files", "rm", "notes.md", "--space", "receiver"]);
    assert_eq!(deleted, added);
    assert!(!copy.exists());
    let unconfirmed = fixture.run(&["files", "rm", "--all"]);
    assert!(!unconfirmed.status.success(), "{unconfirmed:?}");
    assert_eq!(
        fixture.ok(&["files", "rm", "--all", "--yes"]),
        serde_json::json!([])
    );
}

#[test]
fn a_chats_agent_attaches_files_the_user_lists_after_the_chat_ends() {
    let fixture = Fixture::new();
    let repository = fixture.ok(&["repo", "ls"])[0].clone();
    // The sleep stands in for the chat's agent.
    let mut agent = Command::new("sleep").arg("600").spawn().unwrap();
    let response = fixture.request(serde_json::json!({"start_chat":{
        "repository": repository["id"], "name": "planning", "agent": "claude",
        "pid": agent.id()
    }}));
    assert_eq!(response["type"], "chat", "{response}");
    let chat = response["data"]["id"].as_str().unwrap().to_owned();
    fs::write(fixture.repo.join("report.md"), "Plan").unwrap();
    let in_chat = |args: &[&str]| {
        let output = fixture
            .command()
            .current_dir(&fixture.repo)
            .env("SHOAL_CHAT", &chat)
            .arg("--json")
            .args(args)
            .output()
            .unwrap();
        assert!(output.status.success(), "{output:?}");
        serde_json::from_slice::<Value>(&output.stdout).unwrap()
    };

    // The chat's agent attaches, lists and deletes its chat's files.
    let added = in_chat(&["files", "add", "report.md#Plan"]);
    assert_eq!(added[0]["chat"], "planning", "{added}");
    assert!(added[0].get("workspace").is_none(), "{added}");
    assert_eq!(added[0]["title"], "Plan", "{added}");
    assert_eq!(
        added[0]["attached_by"],
        serde_json::json!({"kind": "chat", "agent": "claude", "chat": chat}),
        "{added}"
    );
    let copy = PathBuf::from(added[0]["path"].as_str().unwrap());
    assert!(copy.to_str().unwrap().contains(&chat), "{added}");
    assert_eq!(in_chat(&["files"]), added);
    fs::write(fixture.repo.join("draft.md"), "Draft").unwrap();
    in_chat(&["files", "add", "draft.md"]);
    let deleted = in_chat(&["files", "rm", "draft.md", "--yes"]);
    assert_eq!(deleted[0]["name"], "draft.md", "{deleted}");
    // The user reaches them by the chat's name, which completion offers,
    // or picks the chat among the spaces.
    assert_eq!(fixture.ok(&["files", "planning"]), added);
    let state = fixture.root.path().join("state");
    let words = [
        "shoal",
        "--state-dir",
        state.to_str().unwrap(),
        "files",
        "add",
        "report.md",
        "--space",
        "pl",
    ];
    let completed = fixture
        .command()
        .arg("--")
        .args(words)
        .env("SHOAL_COMPLETE", "bash")
        .env("_CLAP_COMPLETE_INDEX", (words.len() - 1).to_string())
        .output()
        .unwrap();
    assert!(completed.status.success(), "{completed:?}");
    let completed = String::from_utf8(completed.stdout).unwrap();
    assert!(
        completed.lines().any(|line| line == "planning"),
        "{completed}"
    );
    let (output, rows) = fixture.pick(&["files", "--print"], &chat, "");
    assert!(output.status.success(), "{output:?}");
    assert!(
        rows.lines().any(|row| row.starts_with(chat.as_str())),
        "{rows}"
    );
    assert!(
        String::from_utf8_lossy(&output.stdout).contains("report.md"),
        "{output:?}"
    );

    // A stopped chat keeps its files; once it is removed, they stay listed
    // with when they go.
    agent.kill().unwrap();
    agent.wait().unwrap();
    let stopped = fixture.ok(&["files", "planning"]);
    assert!(stopped[0]["expires_at"].is_null(), "{stopped}");
    fixture.ok(&["resume", "planning", "--discard"]);
    let kept = fixture.ok(&["files", "planning"]);
    assert_eq!(kept[0]["path"], added[0]["path"], "{kept}");
    assert!(kept[0]["expires_at"].is_i64(), "{kept}");
    assert_eq!(kept[0]["chat"], "planning", "{kept}");
    assert_eq!(fs::read_to_string(&copy).unwrap(), "Plan");
    let deleted = fixture.ok(&["files", "rm", "--space", "planning"]);
    assert_eq!(deleted[0]["path"], added[0]["path"], "{deleted}");
    assert!(!copy.exists());
}

#[test]
fn done_hands_back_files_that_shoal_files_lists() {
    // Kept, so the workspace stays to show its completion.
    let fixture = Fixture::with_config(Some("[cleanup.done]\nenabled = false\n"));
    fixture.add("audit");
    fs::write(fixture.root.path().join("report.md"), "No leaks").unwrap();
    let missing = fixture.run(&["done", "audit", "--attach", "/missing/report.md"]);
    assert!(!missing.status.success(), "{missing:?}");
    assert!(fixture.ok(&["work", "status", "audit"])["completion"].is_null());

    let output = fixture
        .command()
        .current_dir(fixture.root.path())
        .args([
            "--json",
            "done",
            "audit",
            "--attach",
            "report.md#Audit findings",
        ])
        .output()
        .unwrap();
    assert!(output.status.success(), "{output:?}");
    let completion: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(
        completion["results"][0]["name"], "report.md",
        "{completion}"
    );
    let files = fixture.ok(&["files", "audit"]);
    assert_eq!(files[0]["source"], "result", "{files}");
    assert_eq!(files[0]["title"], "Audit findings", "{files}");
    let result = files[0]["path"].as_str().unwrap();
    assert_eq!(fs::read_to_string(result).unwrap(), "No leaks");
}

