#[test]
fn repository_resources_validate_targets_before_claiming_and_bind_approvals() {
    let fixture = Fixture::new();
    let related = init_repo(fixture.root.path(), "server", &[("tracked", "server\n")]);
    fixture.ok(&["repo", "add", related.to_str().unwrap(), "--name", "server"]);
    set_repository_toml(
        &fixture,
        "[resources.server]\nkind='repo'\nrepo='server'\nrequires_approval=true\n",
    );
    fixture.add("consumer");
    set_repository_toml(
        &fixture,
        "[resources.server]\nkind='repo'\nrepo='missing'\n",
    );
    let missing = fixture.run(&["acquire", "repo", "server", "--workspace", "consumer"]);
    assert!(!missing.status.success());
    assert!(
        fixture.ok(&["work", "status", "consumer"])["resources"]
            .as_array()
            .unwrap()
            .is_empty()
    );
    set_repository_toml(
        &fixture,
        "[resources.server]\nkind='repo'\nrepo='server'\nrequires_approval=true\n",
    );
    let moved = fixture.root.path().join("moved-server");
    fs::rename(&related, &moved).unwrap();
    let unavailable = fixture.run(&["acquire", "repo", "server", "--workspace", "consumer"]);
    assert!(!unavailable.status.success());
    fs::rename(&moved, &related).unwrap();
    let pending = pending_approval(scoped_command(
        &fixture,
        "consumer",
        &[
            "acquire",
            "repo",
            "server",
            "--reason",
            "Read server contract",
        ],
    ));
    assert_eq!(
        pending["specification"]["repository"]["path"],
        related.to_str().unwrap()
    );
    fixture.ok(&[
        "approvals",
        "--approve",
        pending["number"].as_str().unwrap(),
    ]);
    // Reusing the configured name for another registration cannot reuse approval.
    fixture.ok(&["repo", "rm", "server", "--yes"]);
    let replacement = init_repo(
        fixture.root.path(),
        "replacement",
        &[("tracked", "other\n")],
    );
    fixture.ok(&[
        "repo",
        "add",
        replacement.to_str().unwrap(),
        "--name",
        "server",
    ]);
    let changed = scoped_command(&fixture, "consumer", &["acquire", "repo", "server"]);
    assert!(!changed.status.success());
    fixture.ok(&[
        "release",
        "repo",
        "server",
        "--workspace",
        "consumer",
        "--name",
        "default",
    ]);
    let pending = pending_approval(scoped_command(
        &fixture,
        "consumer",
        &[
            "acquire",
            "repo",
            "server",
            "--reason",
            "Read replacement contract",
        ],
    ));
    fixture.ok(&[
        "approvals",
        "--approve",
        pending["number"].as_str().unwrap(),
    ]);
    let granted = scoped_command(&fixture, "consumer", &["acquire", "repo", "server"]);
    assert!(
        granted.status.success(),
        "{}",
        String::from_utf8_lossy(&granted.stderr)
    );
    let lease: Value = serde_json::from_slice(&granted.stdout).unwrap();
    assert_eq!(lease["repository"]["path"], replacement.to_str().unwrap());
}

#[test]
fn redirected_requests_are_inspected_without_prompting_or_deciding() {
    let fixture = Fixture::new();
    set_repository_toml(&fixture, "[ports.web]\nrequires_approval=true\n");
    fixture.add("agent");
    let pending = pending_approval(scoped_command(
        &fixture,
        "agent",
        &["acquire", "port", "web", "--reason", "serve preview"],
    ));
    let question = fixture.ok(&[
        "questions",
        "ask",
        "Which database?",
        "--recommend",
        "SQLite",
        "--space",
        "agent",
    ]);
    install_test_script(fixture.root.path().join("bin/fzf"), "#!/bin/sh\nexit 77\n");
    for args in [
        vec![
            "approvals".to_owned(),
            pending["number"].as_str().unwrap().to_owned(),
        ],
        vec!["approvals".into()],
        vec![
            "questions".into(),
            question["number"].as_str().unwrap().to_owned(),
        ],
        vec!["questions".into()],
    ] {
        let (output, transcript) =
            fixture.interactive_command(fixture.command().args(&args), "y\n");
        assert!(output.status.success(), "{args:?}: {output:?} {transcript}");
        let details = String::from_utf8_lossy(&output.stdout);
        assert!(
            details.contains("serve preview") || details.contains("Which database?"),
            "{details}"
        );
        assert!(
            !transcript.contains("[y/n]") && !transcript.contains("[SQLite]:"),
            "{transcript}"
        );
    }
    assert_eq!(
        fixture.ok(&["approvals", pending["number"].as_str().unwrap()])["status"],
        "pending"
    );
    assert_eq!(
        fixture.ok(&["questions", question["number"].as_str().unwrap()])["answer"],
        Value::Null
    );
    // An explicit decision remains scriptable with redirected output.
    let (output, transcript) = fixture.interactive_command(
        fixture
            .command()
            .args(["approvals", pending["number"].as_str().unwrap(), "--deny"]),
        "",
    );
    assert!(output.status.success(), "{output:?} {transcript}");
    assert_eq!(
        fixture.ok(&["approvals", pending["number"].as_str().unwrap()])["status"],
        "denied"
    );
}

