#[test]
fn any_space_opens_any_kind_of_child() {
    let fixture = Fixture::with_config(Some(
        "[agents.claude]\ncommand = ['sh', './chat-agent.sh']\n",
    ));
    let home = fixture.root.path();
    install_test_script(home.join("bin").join("zmx"), terminal_zmx());
    // The first chat's agent starts a chat below its own; each records its
    // chat and keeps running.
    fs::write(
        fixture.repo.join("chat-agent.sh"),
        format!(
            "shoal='{}'\n\
             if [ ! -e \"$HOME/nested-started\" ]; then\n\
             touch \"$HOME/nested-started\"\n\
             \"$shoal\" start --chat --agent claude --name nested </dev/null > \"$HOME/nested-chat\" 2>&1\n\
             fi\n\
             echo \"$SHOAL_CHAT\" >> \"$HOME/chats-started\"\n\
             trap 'exit 0' TERM\n\
             while :; do sleep 1; done\n",
            support::shoal_binary()
        ),
    )
    .unwrap();
    fixture.add("parent");
    // A workspace's agent opens a workspace below its own...
    let repo = fixture.repo.to_str().unwrap();
    let below = scoped_command(&fixture, "parent", &["start", repo, "below"]);
    assert!(below.status.success(), "{below:?}");
    let parent = |space: &Value| space["parent"]["name"].as_str().map(str::to_owned);
    let status = fixture.ok(&["work", "status", "below"]);
    assert_eq!(parent(&status["workspace"]).as_deref(), Some("parent"));
    // ...but not a chat in its own terminal, whose processes would be its
    // own...
    let here = scoped_command(
        &fixture,
        "parent",
        &["start", "--chat", "--here", "--agent", "claude"],
    );
    assert!(!here.status.success(), "{here:?}");
    // ...nor one in the worktree of a workspace outside its tree...
    fixture.add("other");
    let args = ["start", "--in", "other", "--agent", "claude"];
    let outside = scoped_command(&fixture, "parent", &args);
    assert!(!outside.status.success(), "{outside:?}");
    // ...rather a chat below it, which opens in the background, as its agent
    // cannot hand over a terminal; that chat's agent opens one below its own.
    // The process returns once the chat holds its own scope, which outlasts
    // the process's.
    let sub = scoped_command(
        &fixture,
        "parent",
        &["start", "--chat", "--agent", "claude", "--name", "sub"],
    );
    assert!(sub.status.success(), "{sub:?}");
    wait_until("both chats started", || {
        fs::read_to_string(home.join("chats-started")).is_ok_and(|ids| ids.lines().count() == 2)
    });
    let chats = fixture.ok(&["work", "--chats"]);
    let chat = |name: &str| {
        let found = chats
            .as_array()
            .unwrap()
            .iter()
            .find(|chat| chat["name"] == name);
        found.unwrap_or_else(|| panic!("{name}: {chats}")).clone()
    };
    assert_eq!(parent(&chat("sub")).as_deref(), Some("parent"), "{chats}");
    assert_eq!(chat("sub")["parent"]["kind"], "workspace");
    assert_eq!(parent(&chat("nested")).as_deref(), Some("sub"), "{chats}");
    assert_eq!(chat("nested")["parent"]["kind"], "chat");
    // Removing the workspace takes every space below it, deepest first.
    let removed = fixture.ok(&["rm", "parent", "--yes"]);
    let children: Vec<_> = (removed["children"].as_array().unwrap().iter())
        .map(|name| name.as_str().unwrap().to_owned())
        .collect();
    assert_eq!(children.len(), 3, "{removed}");
    for name in ["below", "sub", "nested"] {
        assert!(
            children.iter().any(|child| child == name),
            "{name}: {removed}"
        );
    }
    assert!(
        children.iter().position(|child| child == "nested")
            < children.iter().position(|child| child == "sub")
    );
    assert_eq!(fixture.ok(&["work", "--chats"]), serde_json::json!([]));
}

/// A chat between two workspaces decides for and coordinates the workspace
/// below it, whose process reaches nothing above, and goes with the
/// workspace above it.
#[test]
fn a_chat_between_workspaces_decides_and_coordinates_for_the_one_below() {
    let fixture = Fixture::with_config(Some(
        "[agents.claude]\ncommand = ['sh', '-c', 'exec sh \"$HOME/agent.sh\"']\n",
    ));
    set_repository_toml(&fixture, "[ports.web]\nrequires_approval=true\n");
    let home = fixture.root.path();
    install_test_script(home.join("bin").join("zmx"), terminal_zmx());
    // The chat's agent opens a workspace below its chat and keeps running;
    // that workspace's agent asks for a port that needs approval.
    fs::write(
        home.join("agent.sh"),
        format!(
            "shoal='{}'\n\
             if [ -n \"$SHOAL_WORKSPACE_ID\" ]; then\n\
             \"$shoal\" --json acquire port web --reason 'serve preview' > \"$HOME/asked.tmp\" 2>&1\n\
             mv \"$HOME/asked.tmp\" \"$HOME/asked\"\n\
             while [ ! -e \"$HOME/release\" ]; do sleep 0.1; done\n\
             exit 0\n\
             fi\n\
             \"$shoal\" start \"$PWD\" deep </dev/null > \"$HOME/deep\" 2>&1\n\
             touch \"$HOME/chat-ready\"\n\
             trap 'exit 0' TERM\n\
             while :; do sleep 1; done\n",
            support::shoal_binary()
        ),
    )
    .unwrap();
    fixture.add("top");
    let middle = scoped_command(
        &fixture,
        "top",
        &["start", "--chat", "--agent", "claude", "--name", "middle"],
    );
    assert!(middle.status.success(), "{middle:?}");
    wait_until("the chat's workspace", || home.join("chat-ready").exists());
    let deep = fixture.ok(&["work", "status", "deep"]);
    assert_eq!(deep["workspace"]["parent"]["name"], "middle", "{deep}");
    let chats = fixture.ok(&["work", "--chats"]);
    let middle = chats[0]["id"].as_str().unwrap().to_owned();
    assert_eq!(chats[0]["parent"]["name"], "top", "{chats}");

    // The running chat, not the agentless workspace above it, decides what
    // the agent of the workspace below asks for.
    let mut worker = fixture
        .command()
        .args(["claude", "deep"])
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .spawn()
        .unwrap();
    wait_until("the worker's request", || home.join("asked").exists());
    let asked: Value =
        serde_json::from_str(&fs::read_to_string(home.join("asked")).unwrap()).unwrap();
    let request = fixture.ok(&["approvals", asked["request"]["number"].as_str().unwrap()]);
    assert_eq!(request["decider"], middle.as_str(), "{request}");
    // The chat coordinates it: the workspace's activity reaches the chat.
    fixture.ok(&["alerts", "send", "--space", "deep", "Tests pass"]);
    let messages = fixture.ok(&["messages", "middle"]);
    assert!(messages.to_string().contains("Tests pass"), "{messages}");
    // The workspace's process reaches neither the chat nor the workspace
    // above it.
    for space in ["middle", "top"] {
        let refused = scoped_command(
            &fixture,
            "deep",
            &["messages", "send", "--space", space, "hi"],
        );
        assert!(!refused.status.success(), "{space}: {refused:?}");
    }
    fs::write(home.join("release"), "").unwrap();
    assert!(worker.wait().unwrap().success());
    // Removing the top workspace takes the chat and the workspace below it.
    let removed = fixture.ok(&["rm", "top", "--yes"]);
    assert_eq!(
        removed["children"],
        serde_json::json!(["deep", "middle"]),
        "{removed}"
    );
    assert_eq!(fixture.ok(&["work"]), serde_json::json!([]));
    assert_eq!(fixture.ok(&["work", "--chats"]), serde_json::json!([]));
}

#[test]
fn chat_instructions_append_the_chat_rules_to_shoals_description() {
    let fixture = Fixture::new();
    install_recording_agent(&fixture, "claude");
    let config_dir = fixture.root.path().join(".config/shoal");
    fs::create_dir_all(config_dir.join("rules")).unwrap();
    fs::write(config_dir.join("rules/chat.md"), "Discuss {repo} at {path}").unwrap();
    fs::create_dir_all(fixture.repo.join(".shoal/rules")).unwrap();
    fs::write(
        fixture.repo.join(".shoal/rules/chat.md"),
        "Plans live in docs {branch}",
    )
    .unwrap();
    let checkout = fs::canonicalize(&fixture.repo).unwrap();
    let chat = || {
        let (output, transcript) = fixture.terminal_command(
            fixture
                .command()
                .current_dir(&fixture.repo)
                .env("ZMX_SESSION", "outer")
                .args(["start", "--chat", "--agent", "claude"]),
            "\n",
            true,
        );
        assert!(output.status.success(), "{output:?}\n{transcript}");
        chat_args(&fixture)
    };
    let name = checkout.file_name().unwrap().to_str().unwrap();
    let args = chat();
    assert_eq!(args[0], "--append-system-prompt");
    let description = format!(
        "You are chatting with the user about the {name} repository in its registered\n\
         checkout at {}.",
        checkout.display()
    );
    assert!(args[1].starts_with(&description), "{}", args[1]);
    assert!(
        args[1].ends_with(&format!(
            "\n\nDiscuss {name} at {}\n\nPlans live in docs {{branch}}",
            checkout.display()
        )),
        "{}",
        args[1]
    );
    // Without additions, Shoal's facts, space rules and `work` rule stand alone.
    fs::write(config_dir.join("rules/chat.md"), "").unwrap();
    fs::write(fixture.repo.join(".shoal/rules/chat.md"), "").unwrap();
    let args = chat();
    assert!(args[1].starts_with(&description), "{}", args[1]);
    assert_eq!(
        guidance_end(&args[1], 0),
        Some(args[1].len()),
        "{}",
        args[1]
    );
}

/// A chat in a workspace runs its agent in the worktree as a chat, told
/// not to edit; workspace commands it runs act on the workspace, and
/// removing the workspace lists and removes the chat first.
#[test]
fn a_chat_runs_in_a_workspaces_worktree_and_goes_with_it() {
    let fixture = Fixture::new();
    let home = fixture.root.path();
    install_recording_agent(&fixture, "claude");
    fixture.add("worker");
    let worktree = fs::canonicalize(
        fixture.ok(&["work", "status", "worker"])["workspace"]["path"]
            .as_str()
            .unwrap(),
    )
    .unwrap();
    // Without a value, the flag takes the current workspace. The chat takes
    // none of the identity a shell Shoal opened there carries.
    let (output, transcript) = fixture.terminal_command(
        fixture
            .command()
            .current_dir(&worktree)
            .env("ZMX_SESSION", "outer")
            .env("SHOAL_WORKSPACE_ID", "worker-id")
            .env("SHOAL_WORKSPACE", "worker")
            .args(["start", "--in", "--agent", "claude"]),
        "\n",
        true,
    );
    assert!(output.status.success(), "{output:?}\n{transcript}");
    assert_eq!(
        fs::read_to_string(home.join("chat-cwd")).unwrap().trim(),
        worktree.to_str().unwrap()
    );
    assert_eq!(
        fs::read_to_string(home.join("chat-workspace")).unwrap(),
        "\n"
    );
    let args = chat_args(&fixture);
    assert_eq!(args[0], "--append-system-prompt");
    assert!(args[1].contains("worker"), "{}", args[1]);
    let chats = fixture.ok(&["work", "--chats"]);
    let chat = &chats[0];
    assert_eq!(chat["name"], "worker-chat", "{chats}");
    assert_eq!(chat["workspace"]["name"], "worker", "{chats}");
    let id = chat["id"].as_str().unwrap();
    assert_eq!(fs::read_to_string(home.join("chat-id")).unwrap().trim(), id);

    // Workspace commands the chat runs act on the workspace, which its
    // scope reads but does not change.
    let scope = fs::read_to_string(home.join("chat-scope")).unwrap();
    let in_chat = |args: &[&str]| {
        fixture
            .command()
            .current_dir(&worktree)
            .env("SHOAL_CHAT", id)
            .env("SHOAL_SCOPE_TOKEN", scope.trim())
            .arg("--json")
            .args(args)
            .output()
            .unwrap()
    };
    let status = in_chat(&["work", "status"]);
    assert!(status.status.success(), "{status:?}");
    let status: Value = serde_json::from_slice(&status.stdout).unwrap();
    assert_eq!(status["workspace"]["name"], "worker", "{status}");
    assert!(in_chat(&["conflicts"]).status.success());
    fs::write(
        worktree.join("tracked"),
        "changed by the workspace's agent\n",
    )
    .unwrap();
    let diff = in_chat(&["diff"]);
    assert!(diff.status.success(), "{diff:?}");
    let diff = String::from_utf8_lossy(&diff.stdout);
    assert!(diff.contains("+changed by the workspace's agent"), "{diff}");
    let view = in_chat(&["view", "--space", "worker", "--no-comments"]);
    assert!(view.status.success(), "{view:?}");
    let change = in_chat(&["branch", "base", "clear"]);
    assert!(!change.status.success(), "{change:?}");
    // A chat in a workspace takes its repository from it.
    let both = fixture.run(&[
        "start",
        "--chat",
        fixture.repo.to_str().unwrap(),
        "--workspace",
        "worker",
    ]);
    assert!(!both.status.success(), "{both:?}");

    // Each status names the other.
    assert_eq!(
        fixture.ok(&["work", "status", "worker"])["chats"][0]["name"],
        "worker-chat"
    );

    // Its agent exited; `shoal resume` restores it in the worktree.
    assert_eq!(chats[0]["restore"], "resume", "{chats}");
    fs::remove_file(home.join("chat-cwd")).unwrap();
    let (output, transcript) = fixture.interactive_command(
        fixture.command().args(["resume", "worker-chat", "--focus"]),
        "",
    );
    assert!(output.status.success(), "{output:?}\n{transcript}");
    assert_eq!(
        fs::read_to_string(home.join("chat-cwd")).unwrap().trim(),
        worktree.to_str().unwrap()
    );
    assert_eq!(fs::read_to_string(home.join("chat-id")).unwrap().trim(), id);

    let (no, prompt) = fixture.interactive(&["rm", "worker"], "n\n");
    assert!(!no.status.success());
    assert!(prompt.contains("worker-chat"), "{prompt}");
    let removed = fixture.run(&["rm", "worker", "--yes"]);
    assert!(removed.status.success(), "{removed:?}");
    assert_eq!(fixture.ok(&["work", "--chats"]), serde_json::json!([]));
}

#[test]
fn chat_starts_from_the_checkout_without_syncing() {
    let fixture = Fixture::new();
    let home = fixture.root.path();
    install_test_script(
        home.join("bin/claude"),
        "#!/bin/sh\ngit rev-parse HEAD > \"$HOME/chat-head\"\nprintf '%s\\0' \"$@\" > \"$HOME/chat-args\"\n",
    );
    let author = upstream_remote(&fixture);
    commit_file(
        &author,
        ".shoal.toml",
        "rules.chat.text = 'Upstream chat guidance'\n",
    );
    git(&author, &["push", "origin", "main"]);
    let chat = || {
        let (output, transcript) = fixture.terminal_command(
            fixture
                .command()
                .current_dir(&fixture.repo)
                .env("ZMX_SESSION", "outer")
                .args(["start", "--chat", "--agent", "claude"]),
            "\n",
            true,
        );
        assert!(output.status.success(), "{output:?}\n{transcript}");
        let head = fs::read_to_string(home.join("chat-head")).unwrap();
        (
            head,
            format!("{}{transcript}", String::from_utf8_lossy(&output.stderr)),
        )
    };
    // An agent that cannot run is refused before the chat starts.
    let (output, transcript) = fixture.interactive_command(
        fixture.command().current_dir(&fixture.repo).args([
            "start",
            "--chat",
            "--agent",
            "happy-claude",
        ]),
        "",
    );
    assert!(!output.status.success(), "{transcript}");
    // The chat starts from the checkout as the sync left it, and the
    // instructions come from that checkout.
    fixture.ok(&["repo", "sync", fixture.repo.to_str().unwrap()]);
    let upstream = git(&author, &["rev-parse", "HEAD"]);
    let (head, output) = chat();
    assert_eq!(head, upstream);
    assert!(!output.contains("Syncing"), "{output}");
    let instructions = &chat_args(&fixture)[1];
    assert!(
        instructions.contains("Upstream chat guidance"),
        "{instructions}"
    );
    // A default branch no sync can fast-forward does not hold the chat back.
    commit_file(&fixture.repo, "local", "local\n");
    let local = git(&fixture.repo, &["rev-parse", "main"]);
    commit_file(&author, "remote", "remote\n");
    git(&author, &["push", "origin", "main"]);
    let (head, _) = chat();
    assert_eq!(head, local);
}

#[test]
fn chat_opens_a_focused_herdr_tab_at_the_checkout() {
    let fixture = Fixture::with_config(Some("terminal.focus = false\n"));
    install_fake_herdr(&fixture);
    install_recording_agent(&fixture, "codex");
    let repository = fixture.ok(&["repo", "ls"])[0].clone();
    let id = repository["id"].as_str().unwrap();
    let checkout = fs::canonicalize(&fixture.repo).unwrap();

    let (caller, transcript) = herdr_call(
        &fixture,
        &[
            "start",
            "--chat",
            fixture.repo.to_str().unwrap(),
            "--agent",
            "codex",
            "--",
            "--search",
        ],
        "\n",
    );
    assert!(caller.status.success(), "{caller:?} {transcript}");
    let create = &herdr_calls(&fixture)[0];
    assert_eq!(create[..2], ["tab", "create"]);
    let option = |name: &str| {
        let at = create.iter().position(|arg| arg == name).unwrap();
        create[at + 1].clone()
    };
    assert_eq!(Path::new(&option("--cwd")), fixture.repo);
    assert_eq!(option("--label"), CHAT_NAME);
    assert!(create.iter().any(|arg| arg == "--focus"));
    let worker = herdr_worker(&fixture);
    let chat = worker.iter().position(|arg| arg == "start").unwrap();
    assert_eq!(
        worker[chat..],
        [
            "start", "--chat", "--mode", "chat", id, "--here", "--name", CHAT_NAME, "--agent",
            "codex", "--", "--search"
        ]
    );
    // The chat registers only once the tab runs it, so nothing is recorded
    // for `attach -` yet; the tab's call records it.
    let history = fixture.root.path().join("state/recent-workspaces.json");
    assert!(!history.exists());
    assert!(
        create.iter().any(|arg| arg == "SHOAL_SHOWN_CHAT=1"),
        "{create:?}"
    );

    // The tab's own call runs the agent in its pane.
    let (output, transcript) = fixture.interactive_command(
        herdr_worker_command(&fixture)
            .current_dir(&fixture.repo)
            .env("HERDR_ENV", "1")
            .env("HERDR_PANE_ID", "w1:p9"),
        "",
    );
    assert!(output.status.success(), "{output:?} {transcript}");
    let chats = fixture.ok(&["work", "--chats"]);
    let recorded: Value = serde_json::from_slice(&fs::read(&history).unwrap()).unwrap();
    assert_eq!(
        recorded["attach"],
        serde_json::json!([chats[0]["id"]]),
        "{chats}"
    );
    assert_eq!(
        fs::read_to_string(fixture.root.path().join("chat-cwd"))
            .unwrap()
            .trim(),
        checkout.to_str().unwrap()
    );
    let args = chat_args(&fixture);
    assert_eq!(args[0], "-c");
    assert!(
        args[1].starts_with("developer_instructions="),
        "{}",
        args[1]
    );
    // It runs a workspace agent's hooks without the subagent brief.
    let hooks = args[2..10].chunks(2).map(|flag| {
        assert_eq!(flag[0], "-c");
        flag[1].split_once('=').unwrap().0
    });
    assert_eq!(
        hooks.collect::<Vec<_>>(),
        [
            "hooks.PostToolUse",
            "hooks.SessionStart",
            "hooks.Stop",
            "hooks.UserPromptSubmit"
        ]
    );
    // Its sandbox lets it reach the daemon.
    assert_eq!(
        args[10..12],
        ["-c", "sandbox_workspace_write.network_access=true"]
    );
    // Codex's default launcher appends its own options after forwarded ones.
    assert_eq!(after_temp_dirs(&args[12..])[0], "--search");
    let codex = fs::read_to_string(fixture.root.path().join(".codex/config.toml")).unwrap();
    assert!(
        codex.contains(checkout.to_str().unwrap()) && codex.contains("trusted"),
        "{codex}"
    );
    assert!(!fixture.root.path().join("zmx-calls").exists());
}

#[test]
fn chat_agents_without_an_instructions_template_get_them_as_their_first_message() {
    let fixture = Fixture::new();
    let repo = fixture.repo.to_str().unwrap();
    let checkout = fs::canonicalize(&fixture.repo).unwrap();
    let chat = |agent: &str| {
        install_recording_agent(&fixture, agent);
        let (output, transcript) = fixture.interactive_command(
            fixture.command().args([
                "start", "--chat", repo, "--agent", agent, "--here", "--", "--fast",
            ]),
            "\n",
        );
        assert!(output.status.success(), "{output:?}\n{transcript}");
        chat_args(&fixture)
    };
    // The message leads the arguments, and asks the agent to wait for the user.
    let args = chat("pi");
    assert_eq!(args.len(), 2, "{args:?}");
    assert!(args[0].contains(checkout.to_str().unwrap()), "{}", args[0]);
    assert_eq!(args[1], "--fast");
    // A launcher with `{prompt}` takes it there.
    assert_eq!(chat("opencode"), ["--prompt", &args[0], "--fast"]);
}

#[test]
fn repository_setup_starts_a_setup_agent_on_the_setup_branch() {
    let fixture = Fixture::new();
    install_recording_agent(&fixture, "claude");
    let repo = fixture.repo.to_str().unwrap();
    let setup = || {
        fixture
            .command()
            .args(["repo", "setup", repo, "--agent", "claude", "--here"])
            .output()
            .unwrap()
    };
    let output = setup();
    assert!(output.status.success(), "{output:?}");

    // The agent works in a workspace on the setup branch, in setup mode.
    let workspace = &fixture.ok(&["work", "status", "shoal-setup"])["workspace"];
    assert_eq!(workspace["branch"], "shoal-setup", "{workspace}");
    assert_eq!(workspace["mode"], "setup", "{workspace}");
    // It is told where the local config goes, which lies in the
    // repository directory it may work in.
    let local_config = PathBuf::from(
        fixture.ok(&["repo", "config", repo])["path"]
            .as_str()
            .unwrap(),
    );
    let directory = fs::canonicalize(local_config.parent().unwrap()).unwrap();
    let args = chat_args(&fixture);
    let repository_dir = directory.parent().unwrap();
    assert!(
        args.contains(&format!("--add-dir={}", repository_dir.display())),
        "{args:?}"
    );
    let prompt = args.last().unwrap();
    let config = directory.join("config.toml");
    assert!(prompt.contains(config.to_str().unwrap()), "{prompt}");

    // A later setup reopens the same workspace.
    let output = setup();
    assert!(output.status.success(), "{output:?}");
    assert_eq!(fixture.ok(&["work"]).as_array().unwrap().len(), 1);
}

#[test]
fn repository_setup_starts_its_agent_past_max_agents() {
    let fixture = Fixture::with_config(Some(
        "machine.max_agents = 1\n[machine.overload.disk]\nenabled = false\n[agents.waiter]\ncommand = ['sh', '-c', 'trap \"exit 0\" TERM; while :; do sleep 1; done']\n",
    ));
    install_recording_agent(&fixture, "claude");
    let repo = fixture.repo.to_str().unwrap();
    let mut first = fixture
        .command()
        .args(["start", repo, "first", "--here", "--agent", "waiter"])
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    wait_until("the first agent start", || {
        fixture
            .ok(&["work"])
            .as_array()
            .unwrap()
            .iter()
            .any(|workspace| workspace["name"] == "first" && workspace["running"] == true)
            && fixture.ok(&["queue"]) == serde_json::json!([])
    });

    let output = fixture
        .command()
        .args(["repo", "setup", repo, "--agent", "claude", "--here"])
        .output()
        .unwrap();
    assert!(output.status.success(), "{output:?}");
    // The setup agent ran instead of waiting for the first agent's slot.
    assert!(!chat_args(&fixture).is_empty());
    assert_eq!(fixture.ok(&["queue"]), serde_json::json!([]));

    fixture.ok(&["stop", "first"]);
    first.wait().unwrap();
}

#[test]
fn repository_setup_refuses_named_arguments_before_any_picker() {
    let fixture = Fixture::new();
    let repo = fixture.repo.to_str().unwrap();
    // Outside the checkout, an omitted repository is picked, too.
    for args in [
        &["repo", "setup", "missing-repository"][..],
        &["repo", "setup", repo, "--agent", "missing-agent"],
    ] {
        let (output, rows) = fixture.pick(args, "1", "");
        assert!(!output.status.success(), "{args:?}: {output:?}");
        assert!(rows.is_empty(), "{args:?} opened the picker: {rows}");
    }
}

#[test]
fn start_takes_the_mode_an_issues_labels_name() {
    let fixture = Fixture::with_config(Some(
        "[issue]\nplan_label = 'needs-plan'\nplanned_label = 'planned'\n",
    ));
    forge_origin(&fixture);
    install_api_curl(&fixture.root.path().join("bin"));
    for (number, title, labels) in [
        (9, "Pick a cache", vec!["needs-plan"]),
        (5, "Retry uploads", vec!["planned"]),
        (3, "Track releases", vec![]),
    ] {
        let labels: Vec<_> = (labels.iter())
            .map(|name| serde_json::json!({"name": name}))
            .collect();
        script_api(
            fixture.root.path(),
            &format!("repos/team/project/issues/{number}"),
            &serde_json::json!({"number": number, "title": title, "state": "open",
                "body": "", "labels": labels, "pull_request": null,
                "html_url": format!("https://forge.example/team/project/issues/{number}")}),
        );
    }
    install_recording_agent(&fixture, "pi");
    let started_in = || {
        let workspace = fs::read_to_string(fixture.root.path().join("chat-workspace")).unwrap();
        let chat = fs::read_to_string(fixture.root.path().join("chat-id")).unwrap();
        (!workspace.trim().is_empty(), !chat.trim().is_empty())
    };

    // An issue that needs a plan starts the plan mode's chat without asking.
    let (output, rows) = fixture.pick_in(
        &fixture.repo,
        &["start", "--issue", "9", "--agent", "pi", "--here"],
        "",
        "",
    );
    assert!(output.status.success(), "{output:?}");
    assert!(rows.is_empty(), "{rows}");
    assert_eq!(started_in(), (false, true));
    assert!(chat_args(&fixture)[0].contains("`planned`"));

    // A planned issue starts the worker without asking.
    let (output, rows) = fixture.pick_in(
        &fixture.repo,
        &["start", "--issue", "5", "--agent", "pi", "--here"],
        "",
        "",
    );
    assert!(output.status.success(), "{output:?}");
    assert!(rows.is_empty(), "{rows}");
    assert_eq!(started_in(), (true, false));

    // An issue with neither label asks for the mode.
    let (output, rows) = fixture.pick_in(
        &fixture.repo,
        &["start", "--issue", "3", "--agent", "pi", "--here"],
        "plan",
        "",
    );
    assert!(output.status.success(), "{output:?}");
    assert!(rows.contains("worker") && rows.contains("plan"), "{rows}");
    assert_eq!(started_in(), (false, true));

    // An issue of an unregistered repository is not read in this one, so
    // the start still offers to register it.
    let (output, transcript) = fixture.terminal_command(
        fixture
            .command()
            .args(["start", "https://forge.example/team/other/issues/4"])
            .args(["--agent", "pi", "--here"])
            .current_dir(&fixture.repo),
        "n\n",
        false,
    );
    assert!(!output.status.success());
    assert!(
        transcript.contains("Register https://forge.example/team/other"),
        "{transcript}"
    );
}

#[test]
fn plan_mode_opens_a_chat_on_an_issue_that_needs_a_plan() {
    let fixture = Fixture::with_config(Some(
        "[issue]\nplan_label = 'needs-plan'\nplanned_label = 'planned'\n",
    ));
    forge_origin(&fixture);
    // The agents' directory is on the terminal's PATH.
    install_api_curl(&fixture.root.path().join("bin"));
    let issue = |number: u64, title: &str| {
        serde_json::json!({"number": number, "title": title, "state": "open",
            "body": format!("Body of {number}."), "labels": [{"name": "needs-plan"}],
            "html_url": format!("https://forge.example/team/project/issues/{number}"),
            "pull_request": null})
    };
    for (number, title) in [(12, "Clarify retries"), (9, "Pick a cache")] {
        script_api(
            fixture.root.path(),
            &format!("repos/team/project/issues/{number}"),
            &issue(number, title),
        );
    }
    script_api(
        fixture.root.path(),
        "repos/team/project/issues?type=issues&state=open&labels=needs-plan&limit=50&page=1",
        &serde_json::json!([issue(12, "Clarify retries"), issue(9, "Pick a cache")]),
    );
    let plan = |args: &[&str], agent: &str| {
        install_recording_agent(&fixture, agent);
        let (output, transcript) = fixture.interactive_command(
            fixture
                .command()
                .args(["start", "--mode", "plan", "--issue"])
                .args(args)
                .args(["--agent", agent, "--here"])
                .current_dir(&fixture.repo),
            "",
        );
        assert!(output.status.success(), "{output:?}\n{transcript}");
        chat_args(&fixture)
    };

    // The issue opens the chat with the chat rule and the planning task,
    // which swaps the configured labels.
    let args = plan(&["9"], "pi");
    assert_eq!(args.len(), 1, "{args:?}");
    let checkout = fs::canonicalize(&fixture.repo).unwrap();
    assert!(args[0].contains(checkout.to_str().unwrap()), "{}", args[0]);
    for expected in [
        "Pick a cache",
        "https://forge.example/team/project/issues/9",
        "Body of 9.",
        "`needs-plan`",
        "`planned`",
    ] {
        assert!(args[0].contains(expected), "{expected}: {}", args[0]);
    }
    // Without an issue, the open issues labelled as needing a plan are
    // offered; only the plan mode takes that, so no mode is asked for.
    install_recording_agent(&fixture, "pi");
    let (output, rows) = fixture.pick_in(
        &fixture.repo,
        &["start", "--issue", "--agent", "pi", "--here"],
        "12",
        "",
    );
    assert!(output.status.success(), "{output:?}");
    assert!(
        rows.contains("Clarify retries") && rows.contains("Pick a cache"),
        "{rows}"
    );
    assert!(chat_args(&fixture)[0].contains("Clarify retries"));
    // Outside plan mode, --issue names one.
    let output = fixture
        .command()
        .args(["start", "--chat", "--issue", "--agent", "pi"])
        .current_dir(&fixture.repo)
        .output()
        .unwrap();
    assert!(!output.status.success(), "{output:?}");

    // An agent with an instructions template keeps them apart and starts on
    // the task as its prompt.
    // A named agent that cannot start is refused before the issue is chosen.
    let output = fixture
        .command()
        .args([
            "start",
            "--mode",
            "plan",
            "--issue",
            "--agent",
            "missing-agent",
        ])
        .current_dir(&fixture.repo)
        .output()
        .unwrap();
    assert!(!output.status.success());

    let args = plan(&["https://forge.example/team/project/issues/12"], "claude");
    assert_eq!(args[0], "--append-system-prompt");
    assert!(!args[1].contains("Clarify retries"), "{}", args[1]);
    assert!(args.last().unwrap().contains("Clarify retries"), "{args:?}");
    // The chat is named after the issue without asking, beside the stopped
    // chat that planned it before, which keeps its name.
    let started = journal(&fixture)
        .into_iter()
        .rfind(|event| event["kind"] == "chat_started")
        .unwrap();
    assert_eq!(
        started["chat"]["name"],
        "repo-with---quotes----literal-plan-12-2"
    );
}

#[test]
fn a_chat_on_an_issue_is_assigned_the_issue() {
    let fixture = Fixture::new();
    forge_origin(&fixture);
    // The agents' directory is on the terminal's PATH.
    install_api_curl(&fixture.root.path().join("bin"));
    let url = "https://forge.example/team/project/issues/12";
    script_api(
        fixture.root.path(),
        "repos/team/project/issues/12",
        &serde_json::json!({"number": 12, "title": "Clarify retries", "state": "open",
            "body": "Body.", "labels": [], "html_url": url, "pull_request": null}),
    );
    // The chat's agent reads what its chat links.
    install_test_script(
        fixture.root.path().join("bin").join("pi"),
        format!(
            "#!/bin/sh\n'{}' --json view --space \"$SHOAL_CHAT\" --no-comments > \"$HOME/plan-view\"\n",
            support::shoal_binary()
        ),
    );
    let (output, transcript) = fixture.interactive_command(
        fixture
            .command()
            .args([
                "start", "--mode", "plan", "--issue", url, "--agent", "pi", "--here",
            ])
            .current_dir(&fixture.repo),
        "",
    );
    assert!(output.status.success(), "{output:?}\n{transcript}");
    let viewed: Value =
        serde_json::from_str(&fs::read_to_string(fixture.root.path().join("plan-view")).unwrap())
            .unwrap();
    assert_eq!(viewed[0]["url"], url, "{viewed}");
}

#[test]
fn setup_verifies_after_a_concurrent_happy_chat_stops() {
    let fixture = Fixture::with_config(Some(HAPPY_ENABLED));
    let record = install_fake_happy(&fixture);
    install_test_script(
        fixture.repo.join("setup.sh"),
        r#"#!/bin/sh
touch "$HOME/setup-started"
i=0
while [ ! -e "$HOME/setup-release" ]; do
  [ "$i" -lt 3000 ] || exit 99
  sleep 0.1
  i=$((i + 1))
done
"#,
    );
    commit_resource_config(&fixture.repo, "setup.command = 'setup.sh'\n");
    let setup = fixture
        .command()
        .args([
            "--json",
            "start",
            fixture.repo.to_str().unwrap(),
            "concurrent",
        ])
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    wait_until("setup to start before the chat", || {
        fixture.root.path().join("setup-started").exists()
    });

    let started = fixture
        .command()
        .args([
            "--json",
            "start",
            "--chat",
            fixture.repo.to_str().unwrap(),
            "--agent",
            "happy-claude",
        ])
        .env("HAPPY_RECORD", &record)
        .output()
        .unwrap();
    assert!(started.status.success(), "{started:?}");
    let started: Value = serde_json::from_slice(&started.stdout).unwrap();
    wait_until("the Happy fixture to publish its launch", || {
        record.exists()
    });
    let stopped = Command::new("kill")
        .arg(started["chat"]["pid"].to_string())
        .status()
        .unwrap();
    assert!(stopped.success());
    wait_until("the daemon to record the chat stopped", || {
        fixture.ok(&["work", "--chats"])[0]["restore"] == "resume"
    });
    fs::write(fixture.root.path().join("setup-release"), "").unwrap();
    let output = setup.wait_with_output().unwrap();
    assert!(output.status.success(), "{output:?}");
    let workspace: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(workspace["state"], "ready");
}

#[test]
fn happy_chats_run_detached_in_the_checkout_while_their_session_lives() {
    let fixture = Fixture::with_config(Some(HAPPY_ENABLED));
    let record = install_fake_happy(&fixture);
    let repo = fixture.repo.to_str().unwrap();
    let checkout = fs::canonicalize(&fixture.repo).unwrap();
    // Started from a Rex block, a detached chat still runs elsewhere.
    let rex_bin = fixture.root.path().join("rex-bin");
    install_test_script(rex_bin.join("rex"), "#!/bin/sh\nexit 9\n");
    let chat = |agent: &str| {
        let _ = fs::remove_file(&record);
        let output = fixture
            .command()
            .args([
                "--json", "start", "--chat", repo, "--agent", agent, "--", "--model", "test",
            ])
            .env("HAPPY_RECORD", &record)
            .env("REX_SESSION", "session:caller")
            .env("REX_BLOCK", "block:caller")
            .env("REX_BIN_DIR", &rex_bin)
            .output()
            .unwrap();
        assert!(output.status.success(), "{output:?}");
        let started: Value = serde_json::from_slice(&output.stdout).unwrap();
        wait_until("fake happy record", || record.exists());
        (started, fs::read_to_string(&record).unwrap())
    };
    let args = |recorded: &str| -> Vec<String> {
        recorded
            .split_once("args=")
            .unwrap()
            .1
            .split_once("\nscope=")
            .unwrap()
            .0
            .split('\0')
            .filter(|arg| !arg.is_empty())
            .map(str::to_owned)
            .collect()
    };

    // Happy's Claude takes the instructions as arguments and waits.
    let (started, recorded) = chat("happy-claude");
    let chat_record = &started["chat"];
    assert_eq!(chat_record["agent"], "happy-claude");
    assert_eq!(chat_record.get("origin"), None, "{chat_record}");
    assert_eq!(chat_record["name"], CHAT_NAME);
    assert!(
        recorded.contains(&format!("cwd={}\n", checkout.display())),
        "{recorded}"
    );
    assert!(recorded.contains(&format!("chat={}\n", chat_record["id"].as_str().unwrap())));
    assert!(recorded.contains("stdin=eof\nstdout=notty"), "{recorded}");
    let claude = args(&recorded);
    assert_eq!(
        claude[..5],
        [
            "claude",
            "--happy-starting-mode",
            "remote",
            "--started-by",
            "daemon"
        ]
    );
    assert_eq!(claude[5], "--append-system-prompt");
    assert!(
        claude[6].contains(checkout.to_str().unwrap()),
        "{}",
        claude[6]
    );
    assert_eq!(after_temp_dirs(&claude[7..]), ["--model", "test"]);
    assert_eq!(started["prompt_file"], Value::Null);
    // The chat lasts while the session runs, not the command that started it.
    let pid = chat_record["pid"].as_u64().unwrap();
    assert_eq!(
        fixture.ok(&["work", "--chats"]),
        serde_json::json!([chat_record])
    );
    let log = PathBuf::from(started["log"].as_str().unwrap());
    wait_until("the session's output", || {
        fs::read_to_string(&log).is_ok_and(|output| output.contains("hello from happy"))
    });

    // Happy's Codex takes them as its first message, saved here when Happy
    // cannot deliver it.
    let (started, recorded) = chat("happy-codex");
    assert_eq!(started["chat"]["name"], format!("{CHAT_NAME}-2"));
    assert_eq!(
        args(&recorded),
        [
            "codex",
            "--happy-starting-mode",
            "remote",
            "--started-by",
            "daemon",
            "--model",
            "test"
        ]
    );
    let message = fs::read_to_string(started["prompt_file"].as_str().unwrap()).unwrap();
    assert!(message.contains(checkout.to_str().unwrap()), "{message}");
    assert_eq!(started["prompt_delivered"], false);

    for pid in [pid, started["chat"]["pid"].as_u64().unwrap()] {
        Command::new("kill").arg(pid.to_string()).status().unwrap();
    }
    wait_until("the chats to stop", || {
        let chats = fixture.ok(&["work", "--chats"]);
        let chats = chats.as_array().unwrap();
        !chats.is_empty() && chats.iter().all(|chat| chat["restore"] == "resume")
    });
}

#[test]
fn outside_a_checkout_issue_open_picks_a_workspace_and_repo_commands_a_repository() {
    let fixture = Fixture::new();
    let workspace = fixture.add("linked");
    let repository = fixture.ok(&["repo", "ls"])[0].clone();
    let offered = |args: &[&str]| {
        // No row matches the choice, so the picker cancels.
        let (_, rows) = fixture.pick(args, "none", "\n");
        rows.lines()
            .map(|row| row.split('\t').next().unwrap().to_owned())
            .collect::<Vec<_>>()
    };
    // `--link` links the new issue to the workspace picked.
    assert_eq!(
        offered(&["issue", "open", "--title", "Bug", "--link"]),
        [workspace["id"].as_str().unwrap()]
    );
    for args in [
        &["repo", "labels"][..],
        &["issue", "list"],
        &["forge", "reactions"],
    ] {
        assert_eq!(
            offered(args),
            [repository["id"].as_str().unwrap()],
            "{args:?}"
        );
    }
}

#[test]
fn chat_picks_chat_agents_and_refuses_unsupported_launches() {
    let fixture = Fixture::new();
    install_fake_agents(&fixture, &["claude", "happy"]);
    let repo = fixture.repo.to_str().unwrap();
    // Without a default agent a picker offers the installed agents that can run.
    let (output, rows) = fixture.pick(&["start", "--chat", repo, "--mode", "chat"], "0", "\n");
    assert!(output.status.success(), "{output:?}");
    assert_eq!(
        rows.lines()
            .map(|row| row.split('\t').nth(1).unwrap())
            .collect::<Vec<_>>(),
        ["claude"]
    );
    // An agent that cannot run a chat is refused before the mode picker.
    let args = ["start", "--chat", repo, "--agent", "happy-claude"];
    let (output, rows) = fixture.pick(&args, "chat", "");
    assert!(!output.status.success(), "{output:?}");
    assert!(rows.is_empty(), "a picker opened: {rows}");
    let output = fixture.run(&["start", "--chat", repo, "--agent", "claude"]);
    assert!(!output.status.success());
    // The checkout has no value for a workspace's placeholders.
    fs::write(
        fixture.repo.join(".shoal.toml"),
        "[agents.claude]\ncommand = ['claude', '--name', '{workspace}']\n",
    )
    .unwrap();
    let (output, transcript) = fixture.interactive_command(
        fixture.command().args([
            "start", "--chat", repo, "--agent", "claude", "--here", "--mode", "chat",
        ]),
        "\n",
    );
    assert!(!output.status.success());
    assert!(transcript.contains("{workspace}"), "{transcript}");
}

#[test]
fn terminal_add_detaches_launches_with_input_and_attaches_the_rest() {
    // `shift` drops Shoal's guidance, the first argument.
    let fixture = Fixture::with_config(Some(
        "machine.max_agents = 1\n[agents.pi]\ncommand = ['sh', '-c', 'shift; echo \"$ZMX_SESSION ${SHOAL_EXECUTION_ID:+tracked} $*\" >> \"$HOME/agent-runs\"', 'agent', '{args}']\n",
    ));
    let home = fixture.root.path();
    let repo = fixture.repo.to_str().unwrap();
    let runs = || fs::read_to_string(home.join("agent-runs")).unwrap_or_default();

    // An agent with input starts in a detached session that runs the plan.
    let (output, transcript) = fixture.terminal_command(
        fixture
            .command()
            .args(["start", repo, "background", "--agent", "pi", "--", "go"]),
        "",
        true,
    );
    assert!(output.status.success(), "{output:?}\n{transcript}");
    wait_until("the detached agent's result", || {
        runs() == "background tracked go\n"
    });
    let calls = zmx_calls(&fixture);
    assert_eq!(calls[1], ["run", "background", "-d", "true"]);
    assert_eq!(calls[2], ["list"]);
    // Only sessions Shoal created carry the creation label.
    assert_eq!(calls[3][..3], ["set", "background", "shoal.created=1"]);
    assert!(calls[3][3].starts_with("shoal.state="), "{calls:?}");
    assert_eq!(calls[4][..2], ["send", "background"]);
    assert!(
        calls[4][2].starts_with("SHOAL_ENDS_SESSION=1 ")
            && calls[4][2].ends_with(
                " internal add --host zmx --close-when-done && exit; exec \"$SHELL\" -l\r"
            ),
        "{calls:?}"
    );
    let session: Value =
        serde_json::from_str(&fs::read_to_string(home.join("zmx-background.env")).unwrap())
            .unwrap();
    assert!(session["SHOAL_ADD_PLAN"].is_string(), "{session}");
    let log = fs::read_to_string(home.join("zmx-background.log")).unwrap_or_default();
    assert_eq!(runs(), "background tracked go\n", "{log}");
    let workspace = fixture.ok(&["work", "status", "background"]);
    let id = workspace["workspace"]["id"].as_str().unwrap();
    let labels = [
        "set",
        "background",
        &format!("shoal.workspace={id}"),
        "shoal.chat=",
    ];
    assert!(
        calls
            .iter()
            .any(|call| call.starts_with(&labels.map(str::to_owned))),
        "{calls:?}"
    );

    // An agent waiting for its first prompt attaches this terminal, which
    // detaching returns to the caller's shell where it was. Its slot must be
    // free in the daemon; the previous agent's output does not prove that.
    wait_until("the detached agent's recorded completion", || {
        fixture.ok(&["work", "status", "background"])["executions"] == serde_json::json!([])
    });
    let directive = home.join("shell-directive");
    let (output, transcript) = fixture.terminal_command(
        fixture
            .command()
            .env("SHOAL_SHELL_DIRECTIVE", &directive)
            .args(["start", repo, "focused", "--agent", "pi"]),
        "",
        true,
    );
    assert!(output.status.success(), "{output:?}\n{transcript}");
    let calls = zmx_calls(&fixture);
    let attach = calls.iter().rfind(|call| call[0] == "attach").unwrap();
    assert_eq!(attach[..2], ["attach", "--labels"]);
    assert_eq!(attach[3], "focused");
    assert_eq!(runs(), "background tracked go\nfocused tracked \n");
    assert!(!directive.exists(), "{transcript}");

    // Without an agent the caller's shell enters the workspace.
    let (output, transcript) = fixture.terminal_command(
        fixture
            .command()
            .env("SHOAL_SHELL_DIRECTIVE", &directive)
            .args(["start", repo, "shell-here", "--focus"]),
        "",
        true,
    );
    assert!(output.status.success(), "{output:?}\n{transcript}");
    let workspace = fixture.ok(&["work", "status", "shell-here"]);
    assert_eq!(
        fs::read_to_string(&directive).unwrap().trim(),
        workspace["workspace"]["path"].as_str().unwrap()
    );
}

